window.JEE_MCQ_BANK = [{"q": "A particle executes SHM with amplitude 5 cm and angular frequency 2 rad/s. Its maximum speed is:", "options": ["0.1 m/s", "0.03 m/s", "0.2 m/s", "0.05 m/s"], "answer": 0, "explanation": "v_max = Aω = 0.05×2 = 0.1 m/s.", "topic": "Physics – Oscillations"}, {"q": "The value of ∫₀^3 x^2 dx is:", "options": ["4.5", "18", "9 × 2", "9"], "answer": 3, "explanation": "[x^3/3]₀^3 = 3^3/3 = 9.", "topic": "Maths – Definite Integrals"}, {"q": "Borax bead test detects:", "options": ["sulphates", "transition metal ions", "halides", "alkali metals"], "answer": 1, "explanation": "Coloured metaborate beads identify transition metal cations.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The unit of the rate constant for a third-order reaction is:", "options": ["s⁻¹", "L·mol⁻¹·s⁻¹", "L²·mol⁻²·s⁻¹", "mol·L⁻¹·s⁻¹"], "answer": 2, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 3 this is L²·mol⁻²·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "The IUPAC name of CH3COCH3 is:", "options": ["propanol", "propanone", "ethanone", "propanal"], "answer": 1, "explanation": "Ketone on a 3-carbon chain → propanone (common: acetone).", "topic": "Chemistry – Organic Chemistry"}, {"q": "Given A → B, ΔH = -50 kJ/mol and B → C, ΔH = -150 kJ/mol, ΔH for A → C is:", "options": ["-100 kJ/mol", "-200 kJ/mol", "200 kJ/mol", "100 kJ/mol"], "answer": 1, "explanation": "Hess's law: ΔH = -50 + (-150) = -200 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "Two vectors of magnitudes 4 and 4 units act at 90° to each other. The magnitude of their resultant is:", "options": ["8 units", "5.66 units × 2", "0 units", "5.66 units"], "answer": 3, "explanation": "R = √(A² + B² + 2ABcosθ) = √(4²+4²+2×4×4×cos90°) = 5.66 units.", "topic": "Physics – Vectors"}, {"q": "A ball is projected with velocity 20 m/s at 60° above the horizontal. The maximum height reached is (g = 10 m/s²):", "options": ["15 m", "7.5 m", "20 m", "30 m"], "answer": 0, "explanation": "H = u²sin²θ/(2g) = 20²×sin²60°/20 = 15 m.", "topic": "Physics – Projectile Motion"}, {"q": "The centre and radius of x² + y² − 2x − 2y + -14 = 0 are:", "options": ["(1, 1), 8", "(2, 2), 4", "(1, 1), 4", "(-1, -1), 4"], "answer": 2, "explanation": "Centre = (−g, −f) = (1, 1); radius = √(g² + f² − c) = 4.", "topic": "Maths – Circles"}, {"q": "The number of terms in the expansion of (x + y)^6 is:", "options": ["6", "8", "7", "12"], "answer": 2, "explanation": "(x + y)ⁿ expands to n + 1 = 7 terms.", "topic": "Maths – Binomial Theorem"}, {"q": "If P(A) = 0.4 and P(B) = 0.5 with A, B independent, then P(A ∩ B) equals:", "options": ["0.1", "0.9", "0.2", "0.45"], "answer": 2, "explanation": "Independent: P(A∩B) = P(A)·P(B) = 0.4×0.5 = 0.2.", "topic": "Maths – Probability"}, {"q": "A long straight wire carries 10 A. The magnetic field at a perpendicular distance 5 cm from it is:", "options": ["20 μT", "40 μT", "160 μT", "80 μT"], "answer": 1, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×10/0.05 = 40 μT.", "topic": "Physics – Magnetism"}, {"q": "For a reaction, ΔH = -100 kJ/mol and ΔS = 200 J/mol·K at 500 K. The reaction is:", "options": ["non-spontaneous", "endothermic and reversible", "spontaneous", "at equilibrium"], "answer": 2, "explanation": "ΔG = ΔH − TΔS = -100 − 500×0.2 = -200 kJ/mol; negative ΔG ⇒ spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "The unit of the rate constant for a first-order reaction is:", "options": ["s⁻¹", "L²·mol⁻²·s⁻¹", "mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹"], "answer": 0, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 1 this is s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "If n(A) = 2 and n(B) = 2, the number of relations from A to B is:", "options": ["4", "8", "16 × 2", "16"], "answer": 3, "explanation": "Relations = subsets of A×B: 2^(n(A)·n(B)) = 2^4 = 16.", "topic": "Maths – Sets & Functions"}, {"q": "The oxidation number of Fe in Fe3O4 is (average):", "options": ["+3", "+2", "+8/3", "+4"], "answer": 2, "explanation": "3x + 4(−2) = 0 ⇒ x = +8/3 (mixed FeO·Fe2O3).", "topic": "Chemistry – Redox Reactions"}, {"q": "The determinant of [[1, 2], [4, 2]] is:", "options": ["-6", "6", "2", "10"], "answer": 0, "explanation": "det = ad − bc = 1×2 − 2×4 = -6.", "topic": "Maths – Matrices & Determinants"}, {"q": "Wurtz reaction of CH3Br with Na gives:", "options": ["propane", "butane", "methane", "ethane"], "answer": 3, "explanation": "2CH3Br + 2Na → CH3CH3 + 2NaBr.", "topic": "Chemistry – Organic Chemistry"}, {"q": "A first-order reaction has k = 0.0693 s⁻¹. Its half-life (in s) is:", "options": ["10 s", "20 s", "5 s", "11 s"], "answer": 0, "explanation": "t½ = 0.693/k = 0.693/0.0693 ≈ 10 s.", "topic": "Chemistry – Chemical Kinetics (numerical)"}, {"q": "100 mL of 0.5 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.05 M", "0.1 M", "0.5 M", "0.2 M"], "answer": 1, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 0.5×100/500 = 0.1 M.", "topic": "Chemistry – Solutions"}, {"q": "The degree of (dy/dx)² + y = x is:", "options": ["3", "1", "2", "not defined"], "answer": 2, "explanation": "Degree = power of the highest-order derivative = 2.", "topic": "Maths – Differential Equations"}, {"q": "The bond order of NO+ is:", "options": ["4", "3.5", "3", "2.5"], "answer": 2, "explanation": "Bond order = (bonding − antibonding electrons)/2; for NO+ this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A 4 kg mass moves in a circle of radius 5 m with speed 10 m/s. The centripetal force on it is:", "options": ["800 N", "8 N", "80 N", "40 N"], "answer": 2, "explanation": "Centripetal force F = mv²/r = 4×10²/5 = 80 N.", "topic": "Physics – Circular Motion"}, {"q": "Increasing temperature increases reaction rate mainly because:", "options": ["the activation energy decreases", "the equilibrium shifts", "more molecules exceed the activation energy", "collisions become elastic"], "answer": 2, "explanation": "The Boltzmann factor e^(−Ea/RT) rises steeply with T, so far more collisions are fruitful.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "At a height 1R above Earth's surface (R = Earth's radius), the acceleration due to gravity is (g at surface):", "options": ["g/2", "g/4", "g", "g/8"], "answer": 1, "explanation": "g_h = g(R/(R+h))² = g/(1+1)² = g/4.", "topic": "Physics – Gravitation"}, {"q": "The nature of the roots of 2x² + 6x + 3 = 0 is:", "options": ["real and equal", "complex (non-real)", "real and distinct × 2", "real and distinct"], "answer": 3, "explanation": "D = b² − 4ac = 6² − 4×2×3 = 12; sign of D gives real and distinct roots.", "topic": "Maths – Quadratic Equations"}, {"q": "A 5 kg block rests on a smooth incline of 30°. The component of its weight parallel to the incline is (g = 10 m/s²):", "options": ["12.5 N", "43.3 N", "25 N", "50 N"], "answer": 2, "explanation": "Parallel component = mg sinθ = 5×10×sin30° = 25 N.", "topic": "Physics – Laws of Motion"}, {"q": "The determinant of [[3, 4], [2, 2]] is:", "options": ["14", "-2", "2", "6"], "answer": 1, "explanation": "det = ad − bc = 3×2 − 4×2 = -2.", "topic": "Maths – Matrices & Determinants"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 4 to n = 3 is:", "options": ["0.66 eV", "0.33 eV", "1.32 eV", "-0.66 eV"], "answer": 0, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/3² − 1/4²) = 0.66 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "The mean of the data 6, 6, 8, 2, 1 is:", "options": ["3.6", "5.6", "4.6", "23"], "answer": 2, "explanation": "Mean = sum/n = 23/5 = 4.6.", "topic": "Maths – Statistics"}, {"q": "If y = 3x^5, then dy/dx equals:", "options": ["15x^6", "15x^4", "3x^4", "15x^5"], "answer": 1, "explanation": "dy/dx = 3×5x^4 = 15x^4.", "topic": "Maths – Differentiation"}, {"q": "The maximum value of y = −2x² + 4x is:", "options": ["1", "3", "2", "4"], "answer": 2, "explanation": "Vertex at x = −B/(2A) = 4/(2×2) = 1; y_max = 2.", "topic": "Maths – Applications of Derivatives"}, {"q": "A convex lens has focal length 25 cm (magnitude). Its power is:", "options": ["-4 D", "0.25 D", "0.04 D", "4 D"], "answer": 3, "explanation": "P = 100/f(cm) = 4 = 4 D.", "topic": "Physics – Ray Optics"}, {"q": "2 mol of an ideal gas expands isothermally at 300 K from V to 2V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["3457.7 J", "1728.85 J", "1501.66 J", "4988.4 J"], "answer": 0, "explanation": "W = nRT ln(V₂/V₁) = 2×8.314×300×ln2 = 3457.7 J.", "topic": "Physics – Thermodynamics"}, {"q": "1 mol of an ideal gas expands isothermally at 300 K from V to 4V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["1501.66 J", "1728.85 J", "3457.7 J", "7482.6 J"], "answer": 2, "explanation": "W = nRT ln(V₂/V₁) = 1×8.314×300×ln4 = 3457.7 J.", "topic": "Physics – Thermodynamics"}, {"q": "3 mol of ideal gas at 2 atm and 273 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["67.24 L", "16.81 L", "33.62 L", "134.48 L"], "answer": 2, "explanation": "V = nRT/P = 3×0.0821×273/2 = 33.62 L.", "topic": "Chemistry – Gaseous State"}, {"q": "A compound contains 40% C, 6.7% H and 53.3% O by mass. Its empirical formula is:", "options": ["CHO", "C2H4O", "CH4O", "CH2O"], "answer": 3, "explanation": "C: 40/12 = 3.33, H: 6.7/1 = 6.7, O: 53.3/16 = 3.33 ⇒ ratio 1:2:1 ⇒ CH2O.", "topic": "Chemistry – Mole Concept"}, {"q": "The nature of the roots of 2x² + 6x + 1 = 0 is:", "options": ["real and distinct", "real and distinct × 2", "complex (non-real)", "real and equal"], "answer": 0, "explanation": "D = b² − 4ac = 6² − 4×2×1 = 28; sign of D gives real and distinct roots.", "topic": "Maths – Quadratic Equations"}, {"q": "A wave of frequency 50 Hz has wavelength 0.5 m. Its speed is:", "options": ["25 m/s", "100 m/s", "12.5 m/s", "50 m/s"], "answer": 0, "explanation": "v = fλ = 50×0.5 = 25 m/s.", "topic": "Physics – Waves"}, {"q": "A wire of length 1 m and cross-section 1 mm² is stretched by 2 mm under a force of 100 N. The elastic potential energy stored is:", "options": ["0.2 J", "0.1 J", "0.1 J × 2", "0.05 J"], "answer": 1, "explanation": "U = ½ × force × extension = ½×100×0 = 0.1 J.", "topic": "Physics – Elasticity"}, {"q": "The limit of (x^5 − 3^5)/(x − 3) as x → 3 is:", "options": ["405", "81", "2025", "243"], "answer": 0, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 5×3ⁿ⁻¹ = 405.", "topic": "Maths – Limits"}, {"q": "A satellite orbits very close to Earth's surface. Its orbital period is approximately:", "options": ["12 hours", "24 hours", "30 days", "84 minutes"], "answer": 3, "explanation": "T = 2π√(R/g) ≈ 84 min for a low Earth orbit.", "topic": "Physics – Gravitation"}, {"q": "The direction cosines of the x-axis are:", "options": ["(0, 1, 0)", "(1, 0, 0)", "(1, 1, 1)", "(0, 0, 1)"], "answer": 1, "explanation": "The x-axis makes angles 0°, 90°, 90° with the axes → (1, 0, 0).", "topic": "Maths – 3D Geometry"}, {"q": "The distance between (1, 1, 0) and (3, 1, 0) is:", "options": ["2", "4", "1", "3"], "answer": 0, "explanation": "d = √(Δx² + Δy² + Δz²) = 2.", "topic": "Maths – 3D Geometry"}, {"q": "Two vectors of magnitudes 5 and 5 units act at 0° to each other. The magnitude of their resultant is:", "options": ["10 units", "0 units", "10 units × 2", "7.07 units"], "answer": 0, "explanation": "R = √(A² + B² + 2ABcosθ) = √(5²+5²+2×5×5×cos0°) = 10 units.", "topic": "Physics – Vectors"}, {"q": "Plaster of Paris is:", "options": ["CaSO4·2H2O", "CaSO4·½H2O", "CaCO3", "CaO"], "answer": 1, "explanation": "Gypsum (CaSO4·2H2O) heated to 393 K gives Plaster of Paris.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The magnitude of vector (1, 4, 2) is:", "options": ["2.29", "4.58", "9.17", "7"], "answer": 1, "explanation": "|v| = √(1² + 4² + 2²) = √21 = 4.58.", "topic": "Maths – Vectors"}, {"q": "Two tuning forks of frequencies 512 Hz and 518 Hz are sounded together. The beat frequency heard is:", "options": ["518 Hz", "6 Hz", "3 Hz", "12 Hz"], "answer": 1, "explanation": "Beat frequency = |f₁ − f₂| = 6 Hz.", "topic": "Physics – Waves"}, {"q": "Two dice are thrown. The probability that the sum is 7 is:", "options": ["7/36", "1/36", "1/12", "1/6"], "answer": 3, "explanation": "Favourable: (1,6),(2,5),(3,4),(4,3),(5,2),(6,1) = 6 of 36 = 1/6.", "topic": "Maths – Probability"}, {"q": "The gauge pressure at depth 10 m in a liquid of density 1000 kg/m³ is (g = 10 m/s²):", "options": ["400 kPa", "100 kPa", "50 kPa", "200 kPa"], "answer": 1, "explanation": "P = ρgh = 1000×10×10 = 100000 Pa = 100 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "The unit of the rate constant for a zero-order reaction is:", "options": ["L²·mol⁻²·s⁻¹", "s⁻¹", "mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹"], "answer": 2, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 0 this is mol·L⁻¹·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "CO2 is linear because carbon is:", "options": ["sp² hybridized", "sp³ hybridized", "unhybridized", "sp hybridized"], "answer": 3, "explanation": "Two double bonds with no lone pairs on C → linear, sp.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The coordination number of Pt in [Pt(NH3)2Cl2] is:", "options": ["2", "3", "6", "4"], "answer": 3, "explanation": "2 NH3 + 2 Cl ligands → coordination number 4.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The bond order of F2 is:", "options": ["1.5", "2", "0.5", "1"], "answer": 3, "explanation": "Bond order = (bonding − antibonding electrons)/2; for F2 this equals 1.", "topic": "Chemistry – Chemical Bonding"}, {"q": "If y = 2x^3, then dy/dx equals:", "options": ["6x^2", "6x^3", "6x^4", "2x^2"], "answer": 0, "explanation": "dy/dx = 2×3x^2 = 6x^2.", "topic": "Maths – Differentiation"}, {"q": "For a zero-order reaction with rate constant k, the half-life is proportional to:", "options": ["nothing; it is constant", "the square of the initial concentration", "the initial concentration", "1/(initial concentration)"], "answer": 2, "explanation": "Zero order: t½ = [A]₀/(2k) ∝ [A]₀ = 0.4 M here.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A 5 kg block on a horizontal surface has coefficient of static friction 0.3. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["7.5 N", "50 N", "15 N", "1.5 N"], "answer": 2, "explanation": "Limiting friction f = μN = μ(mg) = 0.3×5×10 = 15 N.", "topic": "Physics – Laws of Motion"}, {"q": "The value of i^16 (where i = √(−1)) is:", "options": ["-1", "1", "-i", "i"], "answer": 1, "explanation": "i^16 = (i⁴)^4 = 1^4 = 1.", "topic": "Maths – Complex Numbers"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 5 to n = 4 is:", "options": ["0.31 eV", "-0.31 eV", "0.15 eV", "0.61 eV"], "answer": 0, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/4² − 1/5²) = 0.31 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "A projectile is fired with speed 30 m/s at 45° to the horizontal (g = 10 m/s²). Its horizontal range is:", "options": ["90 m", "180 m", "45 m", "127.28 m"], "answer": 0, "explanation": "Range R = u²sin2θ/g; at 45°, sin2θ = 1, so R = 30²/10 = 90 m.", "topic": "Physics – Projectile Motion"}, {"q": "The quadratic equation with roots 3 and 1 is:", "options": ["x² − 4x + 3 = 0", "x² + 4x + 3 = 0", "x² + 3x − 4 = 0", "x² − 4x − 3 = 0"], "answer": 0, "explanation": "x² − (sum)x + (product) = 0 ⇒ x² − 4x + 3 = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "For the Ag electrode with E° = 0.8 V (n = 1) and ion activity giving Q = 0.1, the electrode potential at 298 K is:", "options": ["0.86 V", "0.8 V", "1.72 V", "0.74 V"], "answer": 0, "explanation": "E = E° − (0.0591/n)logQ = 0.8 − (0.0591/1)×log(0.1) = 0.86 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The value of i^4 (where i = √(−1)) is:", "options": ["1", "-i", "i", "-1"], "answer": 0, "explanation": "i^4 = (i⁴)^1 = 1^1 = 1.", "topic": "Maths – Complex Numbers"}, {"q": "The value of C(6, 2) is:", "options": ["30", "15", "14", "16"], "answer": 1, "explanation": "C(6,2) = 6!/(2!(6−2)!) = 15.", "topic": "Maths – Permutations & Combinations"}, {"q": "The nature of the roots of 2x² + 2x + 2 = 0 is:", "options": ["complex (non-real) × 2", "real and distinct", "complex (non-real)", "real and equal"], "answer": 2, "explanation": "D = b² − 4ac = 2² − 4×2×2 = -12; sign of D gives complex (non-real) roots.", "topic": "Maths – Quadratic Equations"}, {"q": "For a reaction, ΔH = 300 kJ/mol and ΔS = 100 J/mol·K at 500 K. The reaction is:", "options": ["spontaneous", "at equilibrium", "non-spontaneous", "endothermic and reversible"], "answer": 2, "explanation": "ΔG = ΔH − TΔS = 300 − 500×0.1 = 250 kJ/mol; negative ΔG ⇒ non-spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "A wave of frequency 200 Hz has wavelength 2 m. Its speed is:", "options": ["400 m/s", "100 m/s", "200 m/s", "800 m/s"], "answer": 0, "explanation": "v = fλ = 200×2 = 400 m/s.", "topic": "Physics – Waves"}, {"q": "An object is placed 60 cm in front of a concave mirror of focal length 15 cm. The image distance is:", "options": ["20 cm × 2", "12 cm", "20 cm", "30 cm"], "answer": 2, "explanation": "1/v = 1/f − 1/u = 1/15 − 1/60 ⇒ v = 20 cm (real, inverted).", "topic": "Physics – Ray Optics"}, {"q": "Two vectors of magnitudes 3 and 4 units act at 60° to each other. The magnitude of their resultant is:", "options": ["1 units", "5 units", "6.08 units", "7 units"], "answer": 2, "explanation": "R = √(A² + B² + 2ABcosθ) = √(3²+4²+2×3×4×cos60°) = 6.08 units.", "topic": "Physics – Vectors"}, {"q": "A bag has 3 red and 2 blue balls. The probability of drawing a red ball is:", "options": ["2/5", "1/3", "3/2", "3/5"], "answer": 3, "explanation": "P(red) = 3/(3+2) = 3/5.", "topic": "Maths – Probability"}, {"q": "The gauge pressure at depth 5 m in a liquid of density 800 kg/m³ is (g = 10 m/s²):", "options": ["40 kPa", "20 kPa", "80 kPa", "160 kPa"], "answer": 0, "explanation": "P = ρgh = 800×10×5 = 40000 Pa = 40 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "Given A → B, ΔH = -100 kJ/mol and B → C, ΔH = -100 kJ/mol, ΔH for A → C is:", "options": ["-200 kJ/mol", "-100 kJ/mol", "0 kJ/mol", "200 kJ/mol"], "answer": 0, "explanation": "Hess's law: ΔH = -100 + (-100) = -200 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "The energy of the electron in the n = 5 shell of He⁺ (Z = 2) is:", "options": ["-1.09 eV", "-0.54 eV", "-0.14 eV", "-2.18 eV"], "answer": 3, "explanation": "Eₙ = −13.6·Z²/n² = −13.6×4/5² = -2.18 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "A wire of length 1 m and cross-section 2 mm² is stretched by 2 mm under a force of 200 N. The elastic potential energy stored is:", "options": ["0.2 J", "0.1 J", "0.2 J × 2", "0.4 J"], "answer": 0, "explanation": "U = ½ × force × extension = ½×200×0 = 0.2 J.", "topic": "Physics – Elasticity"}, {"q": "Saponification of fats gives:", "options": ["fatty acid + water", "ethanol + soap", "glycerol + acid", "glycerol + soap"], "answer": 3, "explanation": "Base hydrolysis of triglycerides → glycerol + fatty acid salts (soap).", "topic": "Chemistry – Organic Chemistry"}, {"q": "The hybridization of Xe in XeF4 is:", "options": ["sp³", "sp³d", "dsp²", "sp³d²"], "answer": 3, "explanation": "XeF4 has 4 bond pairs + 2 lone pairs → octahedral electron geometry, sp³d².", "topic": "Chemistry – Chemical Bonding"}, {"q": "For the reaction N2 + 3H2 ⇌ 2NH3 (ΔH negative), increasing temperature:", "options": ["shifts equilibrium to the left", "shifts equilibrium to the right", "has no effect", "doubles Kc"], "answer": 0, "explanation": "Exothermic forward reaction: higher T favours the endothermic (reverse) direction — Le Chatelier.", "topic": "Chemistry – Equilibrium"}, {"q": "The maximum number of electrons in the n = 3 shell is:", "options": ["18", "9", "32", "8"], "answer": 0, "explanation": "Maximum = 2n² = 2×9 = 18.", "topic": "Chemistry – Atomic Structure"}, {"q": "The number of atoms per unit cell in a diamond cubic lattice is:", "options": ["1", "4", "2", "8"], "answer": 3, "explanation": "FCC (4) + 4 interior atoms = 8 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The gauge pressure at depth 10 m in a liquid of density 800 kg/m³ is (g = 10 m/s²):", "options": ["40 kPa", "160 kPa", "320 kPa", "80 kPa"], "answer": 3, "explanation": "P = ρgh = 800×10×10 = 80000 Pa = 80 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "A 10 μF capacitor is charged to 500 V. The energy stored in it is:", "options": ["2.5 J", "0.62 J", "1.25 J × 2", "1.25 J"], "answer": 3, "explanation": "U = ½CV² = ½×10×10⁻⁶×500² = 1.25 J.", "topic": "Physics – Capacitors"}, {"q": "Copper is refined by:", "options": ["electrolytic refining", "cupellation", "distillation", "zone refining"], "answer": 0, "explanation": "Blister copper is purified by electrolytic refining.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The mean of the data 6, 7, 7, 8, 1 is:", "options": ["5.8", "6.8", "29", "4.8"], "answer": 0, "explanation": "Mean = sum/n = 29/5 = 5.8.", "topic": "Maths – Statistics"}, {"q": "A 2 kg mass moves in a circle of radius 10 m with speed 5 m/s. The centripetal force on it is:", "options": ["2.5 N", "25 N", "5 N", "1 N"], "answer": 2, "explanation": "Centripetal force F = mv²/r = 2×5²/10 = 5 N.", "topic": "Physics – Circular Motion"}, {"q": "A wave of frequency 500 Hz has wavelength 1 m. Its speed is:", "options": ["500 m/s × 2", "250 m/s", "500 m/s", "1000 m/s"], "answer": 2, "explanation": "v = fλ = 500×1 = 500 m/s.", "topic": "Physics – Waves"}, {"q": "cos(2x) in terms of sin x is:", "options": ["1 + 2sin²x", "2sin x", "1 − 2sin²x", "2sin²x − 1"], "answer": 2, "explanation": "Double-angle: cos 2x = 1 − 2sin²x.", "topic": "Maths – Trigonometry"}, {"q": "The freezing point depression of a 1 molal aqueous solution of glucose (van't Hoff factor i = 2, Kf = 1.86 K·kg/mol) is:", "options": ["7.44 K", "3.72 K × 2", "3.72 K", "1.86 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 2×1.86×1 = 3.72 K.", "topic": "Chemistry – Solutions"}, {"q": "A ball is projected with velocity 10 m/s at 30° above the horizontal. The maximum height reached is (g = 10 m/s²):", "options": ["1.25 m", "0.62 m", "2.5 m", "5 m"], "answer": 0, "explanation": "H = u²sin²θ/(2g) = 10²×sin²30°/20 = 1.25 m.", "topic": "Physics – Projectile Motion"}, {"q": "A spring of force constant 100 N/m is stretched by 0.5 m. The elastic potential energy stored is:", "options": ["6.25 J", "50 J", "25 J", "12.5 J"], "answer": 3, "explanation": "U = ½kx² = ½×100×0.5² = 12.5 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "A wire of length 1 m and cross-section 2 mm² is stretched by 2 mm under a force of 100 N. The elastic potential energy stored is:", "options": ["0.2 J", "0.05 J", "0.1 J × 2", "0.1 J"], "answer": 3, "explanation": "U = ½ × force × extension = ½×100×0 = 0.1 J.", "topic": "Physics – Elasticity"}, {"q": "∫₀^π sin(x) dx equals:", "options": ["0", "π", "1", "2"], "answer": 3, "explanation": "[−cos x]₀^π = −cosπ + cos0 = 1 + 1 = 2.", "topic": "Maths – Definite Integrals"}, {"q": "A coil of 200 turns has its flux changed by 0.02 Wb in 0.01 s. The magnitude of induced emf is:", "options": ["400 V", "2 V", "4 V", "200 V"], "answer": 0, "explanation": "|ε| = NΔΦ/Δt = 200×0.02/0.01 = 400 V.", "topic": "Physics – EMI & AC"}, {"q": "A projectile is fired with speed 20 m/s at 45° to the horizontal (g = 10 m/s²). Its horizontal range is:", "options": ["40 m", "56.57 m", "80 m", "20 m"], "answer": 0, "explanation": "Range R = u²sin2θ/g; at 45°, sin2θ = 1, so R = 20²/10 = 40 m.", "topic": "Physics – Projectile Motion"}, {"q": "An object is placed 40 cm in front of a concave mirror of focal length 20 cm. The image distance is:", "options": ["40 cm", "13.33 cm", "40 cm × 3", "40 cm × 2"], "answer": 0, "explanation": "1/v = 1/f − 1/u = 1/20 − 1/40 ⇒ v = 40 cm (real, inverted).", "topic": "Physics – Ray Optics"}, {"q": "For a reaction, ΔH = 150 kJ/mol and ΔS = -150 J/mol·K at 300 K. The reaction is:", "options": ["spontaneous", "at equilibrium", "non-spontaneous", "endothermic and reversible"], "answer": 2, "explanation": "ΔG = ΔH − TΔS = 150 − 300×-0.15 = 195 kJ/mol; negative ΔG ⇒ non-spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "If a = (2, 1, 0) and b = (1, 1, 0), then a·b equals:", "options": ["3", "3 × 2", "2", "4"], "answer": 0, "explanation": "a·b = 2×1 + 1×1 = 3.", "topic": "Maths – Vectors"}, {"q": "The length of the latus rectum of y² = 12x is:", "options": ["12", "24", "6", "3"], "answer": 0, "explanation": "For y² = 4ax, latus rectum = 4a = 12.", "topic": "Maths – Conic Sections"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 4 to n = 2 is:", "options": ["5.1 eV", "1.27 eV", "2.55 eV", "-2.55 eV"], "answer": 2, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/2² − 1/4²) = 2.55 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "In a single throw of a die, the probability of getting a number greater than 3 is:", "options": ["1/2", "1/6", "0.67", "0.5"], "answer": 3, "explanation": "Favourable outcomes: 4, …, 6 → 3 of 6 ⇒ 0.5.", "topic": "Maths – Probability"}, {"q": "Two 3 μF capacitors are connected in series. The equivalent capacitance is:", "options": ["1.5 μF", "6 μF", "2 μF", "3 μF"], "answer": 0, "explanation": "Series: 1/C = 1/3 + 1/3 ⇒ C = 1.5 μF.", "topic": "Physics – Capacitors"}, {"q": "The number of atoms per unit cell in an FCC lattice is:", "options": ["2", "6", "4", "1"], "answer": 2, "explanation": "FCC: 8 corners × 1/8 + 6 faces × 1/2 = 4 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The 10th term of the AP 5, 9, 13, … is:", "options": ["41", "45", "41 × 2", "37"], "answer": 0, "explanation": "Tₙ = a + (n−1)d = 5 + 9×4 = 41.", "topic": "Maths – Sequences & Series"}, {"q": "The hybridization of N in NH4⁺ is:", "options": ["dsp³", "sp³", "sp²", "sp"], "answer": 1, "explanation": "NH4⁺ has 4 sigma bonds → tetrahedral, sp³.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A coil of 50 turns has its flux changed by 0.02 Wb in 0.01 s. The magnitude of induced emf is:", "options": ["50 V", "0.5 V", "100 V", "1 V"], "answer": 2, "explanation": "|ε| = NΔΦ/Δt = 50×0.02/0.01 = 100 V.", "topic": "Physics – EMI & AC"}, {"q": "The median of 3, 7, 9, 12, 15 is:", "options": ["7", "9.4", "12", "9"], "answer": 3, "explanation": "Ordered data has 5 values; the middle (3rd) is 9.", "topic": "Maths – Statistics"}, {"q": "If y = 3x^3, then dy/dx equals:", "options": ["3x^2", "9x^4", "9x^3", "9x^2"], "answer": 3, "explanation": "dy/dx = 3×3x^2 = 9x^2.", "topic": "Maths – Differentiation"}, {"q": "If tan x = 1, then x (in [0, π]) equals:", "options": ["π/2", "π/4", "0", "π/3"], "answer": 1, "explanation": "tan x = 1 ⇒ x = π/4 in [0, π].", "topic": "Maths – Trigonometry"}, {"q": "The value of ∫₀^1 x^3 dx is:", "options": ["0.12", "1", "0.25", "0.5"], "answer": 2, "explanation": "[x^4/4]₀^1 = 1^4/4 = 0.25.", "topic": "Maths – Definite Integrals"}, {"q": "Which is an ambidentate ligand?", "options": ["en", "NH3", "CN⁻", "H2O"], "answer": 2, "explanation": "CN⁻ can bind through C or N (also NO2⁻ through N or O).", "topic": "Chemistry – Coordination Compounds"}, {"q": "Two point charges 2 μC and 3 μC are 0.5 m apart in vacuum. The electrostatic force between them is:", "options": ["2.16 N", "0.22 N", "0.02 N", "0.11 N"], "answer": 1, "explanation": "F = kq₁q₂/r² = 9×10⁹×2×3×10⁻¹²/0.5² = 0.22 N.", "topic": "Physics – Electrostatics"}, {"q": "A body of mass 5 kg has linear momentum 20 kg·m/s. Its kinetic energy is:", "options": ["80 J", "40 J × 2", "20 J", "40 J"], "answer": 3, "explanation": "KE = p²/(2m) = 20²/(2×5) = 40 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "A particle executes SHM with amplitude 10 cm and angular frequency 4 rad/s. Its maximum speed is:", "options": ["0.2 m/s", "1.6 m/s", "0.03 m/s", "0.4 m/s"], "answer": 3, "explanation": "v_max = Aω = 0.1×4 = 0.4 m/s.", "topic": "Physics – Oscillations"}, {"q": "A mass of 1 kg attached to a spring of constant 100 N/m oscillates. Its time period is:", "options": ["0.63 s × 2", "1.26 s", "0.31 s", "0.63 s"], "answer": 3, "explanation": "T = 2π√(m/k) = 2π√(1/100) = 0.63 s.", "topic": "Physics – Oscillations"}, {"q": "The area under y = x from x = 0 to x = 4 (in sq. units) is:", "options": ["8 sq units", "16 sq units", "4 sq units", "9 sq units"], "answer": 0, "explanation": "Area = ∫₀^4 x dx = 4²/2 = 8.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "The shape of XeF2 is:", "options": ["bent", "T-shaped", "pyramidal", "linear"], "answer": 3, "explanation": "3 lone pairs + 2 bond pairs → linear arrangement of F atoms.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The number of moles in 79 g of KMnO4 (molar mass 158 g/mol) is:", "options": ["0.5 mol", "12482 mol", "0.25 mol", "1 mol"], "answer": 0, "explanation": "n = mass/molar mass = 79/158 = 0.5 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The freezing point depression of a 2 molal aqueous solution of glucose (van't Hoff factor i = 3, Kf = 1.86 K·kg/mol) is:", "options": ["5.58 K", "22.32 K", "11.16 K", "3.72 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 3×1.86×2 = 11.16 K.", "topic": "Chemistry – Solutions"}, {"q": "A 2 kg mass moves in a circle of radius 2 m with speed 10 m/s. The centripetal force on it is:", "options": ["10 N", "50 N", "1000 N", "100 N"], "answer": 3, "explanation": "Centripetal force F = mv²/r = 2×10²/2 = 100 N.", "topic": "Physics – Circular Motion"}, {"q": "A constant force of 10 N acts on a body at 60° to its displacement of 5 m. The work done is:", "options": ["25 J", "50 J", "12.5 J", "43.3 J"], "answer": 0, "explanation": "W = Fd cosθ = 10×5×cos60° = 25 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "The sum to infinity of the GP 6, 2, 0.67, … is:", "options": ["4.5", "9", "18", "9 × 2"], "answer": 1, "explanation": "S∞ = a/(1 − r) with r = 1/3: 6/(1 − 1/3) = 9.", "topic": "Maths – Sequences & Series"}, {"q": "Sucrose on hydrolysis gives:", "options": ["glucose + galactose", "glucose + fructose", "fructose + fructose", "glucose + glucose"], "answer": 1, "explanation": "Sucrose (a disaccharide) hydrolyses to one glucose and one fructose.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The domain of f(x) = 1/(x − 2) is:", "options": ["all real x except x = 2", "all real numbers", "x > 2", "x ≥ 2"], "answer": 0, "explanation": "The denominator vanishes at x = 2, so x = 2 is excluded.", "topic": "Maths – Sets & Functions"}, {"q": "The mean of the data 3, 4, 6, 6, 9 is:", "options": ["4.6", "5.6", "28", "6.6"], "answer": 1, "explanation": "Mean = sum/n = 28/5 = 5.6.", "topic": "Maths – Statistics"}, {"q": "The moment of inertia of a solid disc of mass 1 kg and radius 1 m about its central axis is (MR²/2):", "options": ["0.5 kg·m² × 2", "0.25 kg·m²", "1 kg·m²", "0.5 kg·m²"], "answer": 3, "explanation": "I = MR²/2 = 11²/2 = 0.5 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "Iodoform test is positive for:", "options": ["HCHO", "C6H5COCH2CH3", "CH3CH2CHO", "CH3COCH3"], "answer": 3, "explanation": "Methyl ketones (CH3CO–) give CHI3 with I2/NaOH.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The order of basicity in aqueous solution: NH3, CH3NH2, (CH3)2NH is:", "options": ["CH3NH2 > (CH3)2NH > NH3", "(CH3)2NH > CH3NH2 > NH3", "all equal", "NH3 > CH3NH2 > (CH3)2NH"], "answer": 1, "explanation": "+I effect of methyl groups increases basicity; solvation makes 2° > 1° in water.", "topic": "Chemistry – Organic Chemistry"}, {"q": "Chlorination of methane in sunlight proceeds via:", "options": ["free radical mechanism", "electrophilic substitution", "elimination", "nucleophilic substitution"], "answer": 0, "explanation": "hv generates Cl• radicals — a free-radical chain reaction.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The number of angular nodes in a 3d orbital is:", "options": ["3", "1", "0", "2"], "answer": 3, "explanation": "Angular nodes = l = 2 for a d orbital.", "topic": "Chemistry – Atomic Structure"}, {"q": "For a cell with E° = 0.8 V, n = 1 and reaction quotient Q = 0.1, the cell emf at 298 K is:", "options": ["0.74 V", "0.43 V", "0.8 V", "0.86 V"], "answer": 3, "explanation": "Nernst: E = E° − (0.0591/n)logQ = 0.8 − (0.0591/1)log(0.1) = 0.86 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The IUPAC name of [Co(NH3)5Cl]Cl2 is:", "options": ["amminechloridocobalt(III) chloride", "pentaamminechloridocobalt(III) chloride", "pentaamminechloridocobalt(II) dichloride", "chloridopentaamminecobalt(II) chloride"], "answer": 1, "explanation": "5 NH3 (ammine) + 1 Cl (chlorido); Co oxidation state +3; two chloride counter ions.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Mass of copper deposited by 2 A for 30 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["0.04 g", "1.18 g", "0.59 g", "2.37 g"], "answer": 1, "explanation": "m = ItM/(nF) = 2×1800×63.5/(2×96500) = 1.18 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The moment of inertia of a thin ring of mass 1 kg and radius 1 m about its central axis is (MR²):", "options": ["1 kg·m² × 2", "0.5 kg·m²", "1 kg·m²", "2 kg·m²"], "answer": 2, "explanation": "I = MR² = 11² = 1 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The number of molecules in 1 mol of CO2 is:", "options": ["602200000000000027262976 atoms", "6.022×10²³", "1×6.022×10²³", "1×6.022×10²²"], "answer": 2, "explanation": "Molecules = n × NA = 1 × 6.022×10²³.", "topic": "Chemistry – Mole Concept"}, {"q": "Two point charges 1 μC and 4 μC are 0.5 m apart in vacuum. The electrostatic force between them is:", "options": ["0.14 N", "0.07 N", "1.44 N", "0.01 N"], "answer": 0, "explanation": "F = kq₁q₂/r² = 9×10⁹×1×4×10⁻¹²/0.5² = 0.14 N.", "topic": "Physics – Electrostatics"}, {"q": "A radioactive sample has half-life 2 h. The fraction remaining after 4 h is:", "options": ["0.25", "0.5", "0.12", "1.25"], "answer": 0, "explanation": "Fraction = (1/2)^(t/T) = (1/2)^2 = 0.25.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "A mass of 0.25 kg attached to a spring of constant 200 N/m oscillates. Its time period is:", "options": ["0.44 s", "0.22 s", "0.22 s × 2", "0.11 s"], "answer": 1, "explanation": "T = 2π√(m/k) = 2π√(0.25/200) = 0.22 s.", "topic": "Physics – Oscillations"}, {"q": "The limit of (x^5 − 1^5)/(x − 1) as x → 1 is:", "options": ["25", "5", "5 × 2", "1"], "answer": 1, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 5×1ⁿ⁻¹ = 5.", "topic": "Maths – Limits"}, {"q": "The distance between (2, 0, 3) and (4, 0, 3) is:", "options": ["3", "4", "1", "2"], "answer": 3, "explanation": "d = √(Δx² + Δy² + Δz²) = 2.", "topic": "Maths – 3D Geometry"}, {"q": "The value of P(7, 3) is:", "options": ["210", "70", "35", "630"], "answer": 0, "explanation": "P(7,3) = 7!/(7−3)! = 210.", "topic": "Maths – Permutations & Combinations"}, {"q": "The function f(x) = 2x + 3 is:", "options": ["bijective", "neither", "injective only", "surjective only"], "answer": 0, "explanation": "Linear with nonzero slope: one-one and onto over ℝ → bijective.", "topic": "Maths – Sets & Functions"}, {"q": "A card is drawn from a standard deck. The probability it is an ace is:", "options": ["4/13", "1/4", "1/13", "1/52"], "answer": 2, "explanation": "4 aces in 52 cards: 4/52 = 1/13.", "topic": "Maths – Probability"}, {"q": "The freezing point depression of a 2 molal aqueous solution of urea (van't Hoff factor i = 1, Kf = 1.86 K·kg/mol) is:", "options": ["7.44 K", "3.72 K × 2", "3.72 K", "1.86 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 1×1.86×2 = 3.72 K.", "topic": "Chemistry – Solutions"}, {"q": "A transformer has 200 primary and 100 secondary turns. With 110 V applied to the primary, the secondary voltage is:", "options": ["27.5 V", "220 V", "110 V", "55 V"], "answer": 3, "explanation": "V₂/V₁ = N₂/N₁ ⇒ V₂ = 110×100/200 = 55 V.", "topic": "Physics – EMI & AC"}, {"q": "The centre of the ellipse 4x² + 9y² = 36 is:", "options": ["(1, 1)", "(0, 0)", "(4, 9)", "(2, 3)"], "answer": 1, "explanation": "Dividing by 36: x²/9 + y²/4 = 1, centred at the origin.", "topic": "Maths – Conic Sections"}, {"q": "1 mol of an ideal gas expands isothermally at 300 K from V to 3V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["2740.16 J", "1370.08 J", "4988.4 J", "1190.04 J"], "answer": 0, "explanation": "W = nRT ln(V₂/V₁) = 1×8.314×300×ln3 = 2740.16 J.", "topic": "Physics – Thermodynamics"}, {"q": "100 mL of 0.5 M NaOH is diluted to 1000 mL. The molarity of the diluted solution is:", "options": ["0.1 M", "0.03 M", "0.5 M", "0.05 M"], "answer": 3, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 0.5×100/1000 = 0.05 M.", "topic": "Chemistry – Solutions"}, {"q": "The sum of the first 20 terms of the AP 3, 5, … is:", "options": ["220", "480", "440", "880"], "answer": 2, "explanation": "Sₙ = n/2×[2a + (n−1)d] = 20/2×[6 + 19×2] = 440.", "topic": "Maths – Sequences & Series"}, {"q": "A coil of 100 turns has its flux changed by 0.1 Wb in 0.02 s. The magnitude of induced emf is:", "options": ["500 V", "250 V", "2 V", "10 V"], "answer": 0, "explanation": "|ε| = NΔΦ/Δt = 100×0.1/0.02 = 500 V.", "topic": "Physics – EMI & AC"}, {"q": "Light of photon energy 4 eV falls on a metal of work function 2 eV. The maximum kinetic energy of emitted electrons is:", "options": ["-2 eV", "8 eV", "6 eV", "2 eV"], "answer": 3, "explanation": "K_max = hν − φ = 4 − 2 = 2 eV.", "topic": "Physics – Modern Physics"}, {"q": "The limit of sin(x)/x as x → 0 is:", "options": ["does not exist", "∞", "0", "1"], "answer": 3, "explanation": "Standard limit: lim(x→0) sin x/x = 1.", "topic": "Maths – Limits"}, {"q": "200 mL of 2 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.4 M", "1.6 M", "2 M", "0.8 M"], "answer": 3, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 2×200/500 = 0.8 M.", "topic": "Chemistry – Solutions"}, {"q": "The inert pair effect is most prominent in:", "options": ["Si", "C", "Pb", "Ge"], "answer": 2, "explanation": "In group 14, the ns² electrons become increasingly inert down the group; Pb(II) is very stable.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The quadratic equation with roots 2 and 3 is:", "options": ["x² − 5x − 6 = 0", "x² + 6x − 5 = 0", "x² − 5x + 6 = 0", "x² + 5x + 6 = 0"], "answer": 2, "explanation": "x² − (sum)x + (product) = 0 ⇒ x² − 5x + 6 = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "Two resistors of 4 Ω each are joined in parallel. The equivalent resistance is:", "options": ["4 Ω", "6 Ω", "8 Ω", "2 Ω"], "answer": 3, "explanation": "Parallel: 1/R = 1/4 + 1/4 ⇒ R = 2 Ω.", "topic": "Physics – Current Electricity"}, {"q": "Tollens' reagent gives a silver mirror with:", "options": ["alcohols", "carboxylic acids", "aldehydes", "ketones"], "answer": 2, "explanation": "Tollens' oxidises aldehydes (not ketones) to carboxylates, depositing Ag.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The shape of NH3 is:", "options": ["linear", "tetrahedral", "planar", "pyramidal"], "answer": 3, "explanation": "NH3 has 3 bond pairs + 1 lone pair → trigonal pyramidal.", "topic": "Chemistry – Chemical Bonding"}, {"q": "Mass of aluminium deposited by 3 A for 30 min (Al³⁺ + 3e⁻ → Al, M = 27) is:", "options": ["1.01 g", "0.25 g", "0.5 g", "0.06 g"], "answer": 2, "explanation": "m = ItM/(nF) = 3×1800×27/(3×96500) = 0.5 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "A 2 kg block rests on a smooth incline of 30°. The component of its weight parallel to the incline is (g = 10 m/s²):", "options": ["10 N", "20 N", "5 N", "17.32 N"], "answer": 0, "explanation": "Parallel component = mg sinθ = 2×10×sin30° = 10 N.", "topic": "Physics – Laws of Motion"}, {"q": "Hybridization of the carbonyl carbon in aldehydes is:", "options": ["sp³", "dsp²", "sp²", "sp"], "answer": 2, "explanation": "C=O carbon has 3 sigma bonds → trigonal planar, sp².", "topic": "Chemistry – Organic Chemistry"}, {"q": "If det[[2, 1], [2, 3]] = x, then x equals:", "options": ["4", "8", "2", "5"], "answer": 0, "explanation": "x = 2×3 − 1×2 = 4.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "The oxidation number of S in H2SO4 is:", "options": ["+6", "+4", "+8", "+2"], "answer": 0, "explanation": "2(+1) + x + 4(−2) = 0 ⇒ x = +6.", "topic": "Chemistry – Redox Reactions"}, {"q": "The density of O2 at STP (M = 32 g/mol) is approximately:", "options": ["1.43 g/L × 2", "2.86 g/L", "0.71 g/L", "1.43 g/L"], "answer": 3, "explanation": "d = PM/(RT) = 1×32/(0.0821×273) = 1.43 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "A long straight wire carries 10 A. The magnetic field at a perpendicular distance 2 cm from it is:", "options": ["50 μT", "100 μT", "200 μT", "400 μT"], "answer": 1, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×10/0.02 = 100 μT.", "topic": "Physics – Magnetism"}, {"q": "The number of molecules in 2 mol of CO2 is:", "options": ["1204400000000000054525952 atoms", "6.022×10²³", "2×6.022×10²³", "2×6.022×10²²"], "answer": 2, "explanation": "Molecules = n × NA = 2 × 6.022×10²³.", "topic": "Chemistry – Mole Concept"}, {"q": "The number of atoms per unit cell in a hexagonal close packing (HCP) lattice is:", "options": ["4", "6", "2", "1"], "answer": 1, "explanation": "12 corners × 1/6 + 2 face centres × 1/2 + 3 interior = 6 atoms.", "topic": "Chemistry – Solid State"}, {"q": "A 5 μF capacitor is charged to 500 V. The energy stored in it is:", "options": ["0.62 J × 2", "0.31 J", "1.25 J", "0.62 J"], "answer": 3, "explanation": "U = ½CV² = ½×5×10⁻⁶×500² = 0.62 J.", "topic": "Physics – Capacitors"}, {"q": "The value of ∫₀^3 x^1 dx is:", "options": ["9", "4.5", "3", "2.25"], "answer": 1, "explanation": "[x^2/2]₀^3 = 3^2/2 = 4.5.", "topic": "Maths – Definite Integrals"}, {"q": "Two point charges 1 μC and 3 μC are 0.1 m apart in vacuum. The electrostatic force between them is:", "options": ["1.35 N", "0.27 N", "27 N", "2.7 N"], "answer": 3, "explanation": "F = kq₁q₂/r² = 9×10⁹×1×3×10⁻¹²/0.1² = 2.7 N.", "topic": "Physics – Electrostatics"}, {"q": "A long straight wire carries 5 A. The magnetic field at a perpendicular distance 2 cm from it is:", "options": ["100 μT", "25 μT", "50 μT", "200 μT"], "answer": 2, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×5/0.02 = 50 μT.", "topic": "Physics – Magnetism"}, {"q": "For a reaction, ΔH = 150 kJ/mol and ΔS = 100 J/mol·K at 300 K. The reaction is:", "options": ["spontaneous", "at equilibrium", "endothermic and reversible", "non-spontaneous"], "answer": 3, "explanation": "ΔG = ΔH − TΔS = 150 − 300×0.1 = 120 kJ/mol; negative ΔG ⇒ non-spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "The 15th term of the AP 5, 9, 13, … is:", "options": ["61 × 2", "65", "57", "61"], "answer": 3, "explanation": "Tₙ = a + (n−1)d = 5 + 14×4 = 61.", "topic": "Maths – Sequences & Series"}, {"q": "The magnitude of vector (1, 4, 3) is:", "options": ["5.1", "10.2", "2.55", "8"], "answer": 0, "explanation": "|v| = √(1² + 4² + 3²) = √26 = 5.1.", "topic": "Maths – Vectors"}, {"q": "The number of ways to arrange the letters of the word LEVEL is:", "options": ["60", "30", "20", "120"], "answer": 1, "explanation": "5 letters with L twice and E twice: 5!/(2!×2!) = 30.", "topic": "Maths – Permutations & Combinations"}, {"q": "Which hydride is ionic?", "options": ["H2O", "NaH", "NH3", "CH4"], "answer": 1, "explanation": "Alkali metals form ionic (saline) hydrides like NaH.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "For a reaction, ΔH = -100 kJ/mol and ΔS = -150 J/mol·K at 500 K. The reaction is:", "options": ["at equilibrium", "non-spontaneous", "endothermic and reversible", "spontaneous"], "answer": 3, "explanation": "ΔG = ΔH − TΔS = -100 − 500×-0.15 = -25 kJ/mol; negative ΔG ⇒ spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "The number of atoms per unit cell in a simple cubic lattice is:", "options": ["2", "1", "6", "4"], "answer": 1, "explanation": "8 corners × 1/8 = 1 atom.", "topic": "Chemistry – Solid State"}, {"q": "A 2 kg mass moves in a circle of radius 10 m with speed 10 m/s. The centripetal force on it is:", "options": ["10 N", "20 N", "2 N", "200 N"], "answer": 1, "explanation": "Centripetal force F = mv²/r = 2×10²/10 = 20 N.", "topic": "Physics – Circular Motion"}, {"q": "Which of the following is the dimensional formula of energy is?", "options": ["[ML²T⁻¹]", "[ML²T⁻²]", "[MLT⁻²]", "[ML³T⁻²]"], "answer": 1, "explanation": "Work = force × distance gives [MLT⁻²][L] = [ML²T⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The limit of (1 + 2/x)^x as x → ∞ is:", "options": ["e^2", "e", "1", "2e"], "answer": 0, "explanation": "lim(x→∞)(1 + 2/x)^x = e^2.", "topic": "Maths – Limits"}, {"q": "A long straight wire carries 2 A. The magnetic field at a perpendicular distance 2 cm from it is:", "options": ["80 μT", "20 μT", "40 μT", "10 μT"], "answer": 1, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×2/0.02 = 20 μT.", "topic": "Physics – Magnetism"}, {"q": "A wire experiences a stress of 2×10⁸ N/m² and a strain of 0. Its Young's modulus is:", "options": ["200 GPa", "0.2 GPa", "400 GPa", "100 GPa"], "answer": 0, "explanation": "Y = stress/strain = 200000000/0 = 200000000000 Pa = 200 GPa.", "topic": "Physics – Elasticity"}, {"q": "A wire experiences a stress of 1×10⁸ N/m² and a strain of 0. Its Young's modulus is:", "options": ["50 GPa", "0.1 GPa", "100 GPa", "25 GPa"], "answer": 0, "explanation": "Y = stress/strain = 100000000/0 = 50000000000 Pa = 50 GPa.", "topic": "Physics – Elasticity"}, {"q": "Using average bond enthalpies, formation of H2 from 2H atoms is:", "options": ["endothermic (ΔH positive)", "exothermic (ΔH negative)", "athermic", "impossible to predict"], "answer": 1, "explanation": "Bond formation releases energy: ΔH = −(bond enthalpy of H–H) < 0.", "topic": "Chemistry – Thermodynamics"}, {"q": "Aldol condensation of acetaldehyde gives:", "options": ["2-butanol", "crotonaldehyde directly", "butanal", "3-hydroxybutanal"], "answer": 3, "explanation": "Two ethanal molecules form 3-hydroxybutanal (aldol), which can dehydrate to crotonaldehyde.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The oxidation state of Fe in K4[Fe(CN)6] is:", "options": ["+4", "0", "+2", "+3"], "answer": 2, "explanation": "4(+1) + x + 6(−1) = 0 ⇒ x = +2.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Second ionization energy is exceptionally high for:", "options": ["Si", "Al", "Na", "Mg"], "answer": 2, "explanation": "Removing a second electron from Na breaks into the stable noble-gas core (Na⁺ is [Ne]).", "topic": "Chemistry – Periodic Table"}, {"q": "The mean of the data 7, 4, 6, 8, 9 is:", "options": ["34", "6.8", "7.8", "5.8"], "answer": 1, "explanation": "Mean = sum/n = 34/5 = 6.8.", "topic": "Maths – Statistics"}, {"q": "A particle executes SHM with amplitude 5 cm and angular frequency 5 rad/s. Its maximum speed is:", "options": ["0.12 m/s", "0.25 m/s", "1.25 m/s", "0.01 m/s"], "answer": 1, "explanation": "v_max = Aω = 0.05×5 = 0.25 m/s.", "topic": "Physics – Oscillations"}, {"q": "The sum of the first 20 terms of the AP 2, 5, … is:", "options": ["670", "1220", "610", "305"], "answer": 2, "explanation": "Sₙ = n/2×[2a + (n−1)d] = 20/2×[4 + 19×3] = 610.", "topic": "Maths – Sequences & Series"}, {"q": "If a = (1, 2, 0) and b = (2, 1, 0), then a·b equals:", "options": ["5", "4", "4 × 2", "3"], "answer": 1, "explanation": "a·b = 1×2 + 2×1 = 4.", "topic": "Maths – Vectors"}, {"q": "For a reaction, ΔH = -200 kJ/mol and ΔS = 200 J/mol·K at 500 K. The reaction is:", "options": ["spontaneous", "non-spontaneous", "endothermic and reversible", "at equilibrium"], "answer": 0, "explanation": "ΔG = ΔH − TΔS = -200 − 500×0.2 = -300 kJ/mol; negative ΔG ⇒ spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "A spring of force constant 200 N/m is stretched by 0.5 m. The elastic potential energy stored is:", "options": ["12.5 J", "50 J", "100 J", "25 J"], "answer": 3, "explanation": "U = ½kx² = ½×200×0.5² = 25 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "If a = (3, 1, 0) and b = (2, 2, 0), then a·b equals:", "options": ["8", "8 × 2", "7", "9"], "answer": 0, "explanation": "a·b = 3×2 + 1×2 = 8.", "topic": "Maths – Vectors"}, {"q": "3 mol of ideal gas at 0.5 atm and 300 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["73.89 L", "295.56 L", "147.78 L", "36.95 L"], "answer": 2, "explanation": "V = nRT/P = 3×0.0821×300/0.5 = 147.78 L.", "topic": "Chemistry – Gaseous State"}, {"q": "If the absolute temperature of a gas is increased 2-fold, its rms molecular speed becomes:", "options": ["√2 times", "2 times", "unchanged", "2² times"], "answer": 0, "explanation": "v_rms = √(3RT/M) ∝ √T ⇒ increases by √2.", "topic": "Physics – Kinetic Theory"}, {"q": "A body of mass 4 kg has linear momentum 20 kg·m/s. Its kinetic energy is:", "options": ["50 J × 2", "25 J", "100 J", "50 J"], "answer": 3, "explanation": "KE = p²/(2m) = 20²/(2×4) = 50 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "∫ cos(2x) dx equals:", "options": ["−sin(2x)/2 + C", "sin(2x)/2 + C", "2sin(2x) + C", "sin(2x) + C"], "answer": 1, "explanation": "Substitute u = 2x: ∫ cos(2x)dx = sin(2x)/2 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "An electron (charge 1.6×10⁻¹⁹ C) enters a magnetic field of 1 T perpendicularly with speed 1×10⁶ m/s. The magnetic force on it is:", "options": ["0 N × 3", "0 N", "0 N × 2", "0 N × 4"], "answer": 1, "explanation": "F = qvB sin90° = 1.6×10⁻¹⁹×1×10⁶×1 = 0 N.", "topic": "Physics – Magnetism"}, {"q": "Which of the following is the dimensional formula of angular momentum is?", "options": ["[ML³T⁻¹]", "[ML²T⁻²]", "[MLT⁻¹]", "[ML²T⁻¹]"], "answer": 3, "explanation": "L = r × p gives [L][MLT⁻¹] = [ML²T⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "The value of ∫₀^3 x^3 dx is:", "options": ["27", "20.25", "10.12", "40.5"], "answer": 1, "explanation": "[x^4/4]₀^3 = 3^4/4 = 20.25.", "topic": "Maths – Definite Integrals"}, {"q": "The determinant of [[2, 1], [3, 4]] is:", "options": ["8", "11", "5", "-5"], "answer": 2, "explanation": "det = ad − bc = 2×4 − 1×3 = 5.", "topic": "Maths – Matrices & Determinants"}, {"q": "Two point charges 1 μC and 2 μC are 0.1 m apart in vacuum. The electrostatic force between them is:", "options": ["1.8 N", "0.9 N", "18 N", "0.18 N"], "answer": 0, "explanation": "F = kq₁q₂/r² = 9×10⁹×1×2×10⁻¹²/0.1² = 1.8 N.", "topic": "Physics – Electrostatics"}, {"q": "The number of moles in 40 g of NaOH (molar mass 40 g/mol) is:", "options": ["0.5 mol", "1600 mol", "1 mol", "2 mol"], "answer": 2, "explanation": "n = mass/molar mass = 40/40 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The mean of the data 8, 3, 6, 8, 8 is:", "options": ["7.6", "5.6", "33", "6.6"], "answer": 3, "explanation": "Mean = sum/n = 33/5 = 6.6.", "topic": "Maths – Statistics"}, {"q": "The eccentricity of a hyperbola is always:", "options": ["equal to 0", "greater than 1", "equal to 1", "less than 1"], "answer": 1, "explanation": "For hyperbolas e > 1 (e = 1 is a parabola, e < 1 an ellipse).", "topic": "Maths – Conic Sections"}, {"q": "A 5 kg block on a horizontal surface has coefficient of static friction 0.4. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["2 N", "20 N", "10 N", "50 N"], "answer": 1, "explanation": "Limiting friction f = μN = μ(mg) = 0.4×5×10 = 20 N.", "topic": "Physics – Laws of Motion"}, {"q": "The number of radial nodes in a 3p orbital is:", "options": ["1", "2", "0", "3"], "answer": 0, "explanation": "Radial nodes = n − l − 1 = 3 − 1 − 1 = 1.", "topic": "Chemistry – Atomic Structure"}, {"q": "A Carnot engine operates between 600 K and 200 K. Its efficiency is:", "options": ["33.33%", "66.67% × 2", "-200%", "66.67%"], "answer": 3, "explanation": "η = 1 − T₂/T₁ = 1 − 200/600 = 66.67%.", "topic": "Physics – Thermodynamics"}, {"q": "The oxidation number of Cl in HClO4 is:", "options": ["+7", "−1", "+5", "+1"], "answer": 0, "explanation": "+1 + x + 4(−2) = 0 ⇒ x = +7.", "topic": "Chemistry – Redox Reactions"}, {"q": "The limit of (x^2 − 1^2)/(x − 1) as x → 1 is:", "options": ["1", "2", "2 × 2", "4"], "answer": 1, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 2×1ⁿ⁻¹ = 2.", "topic": "Maths – Limits"}, {"q": "A ball is projected with velocity 10 m/s at 60° above the horizontal. The maximum height reached is (g = 10 m/s²):", "options": ["3.75 m", "5 m", "7.5 m", "1.87 m"], "answer": 0, "explanation": "H = u²sin²θ/(2g) = 10²×sin²60°/20 = 3.75 m.", "topic": "Physics – Projectile Motion"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 2 to n = 1 is:", "options": ["5.1 eV", "10.2 eV", "20.4 eV", "-10.2 eV"], "answer": 1, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/1² − 1/2²) = 10.2 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "An engine exerts a constant force of 200 N to keep a vehicle moving at 10 m/s. The power delivered is:", "options": ["2000 W", "4000 W", "3000 W", "1000 W"], "answer": 0, "explanation": "P = F·v = 200×10 = 2000 W.", "topic": "Physics – Work, Energy & Power"}, {"q": "The value of i^12 (where i = √(−1)) is:", "options": ["i", "-i", "-1", "1"], "answer": 3, "explanation": "i^12 = (i⁴)^3 = 1^3 = 1.", "topic": "Maths – Complex Numbers"}, {"q": "The ratio of rates of effusion of H2 to CH4 is:", "options": ["0.35", "1.41", "2.83", "8"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(16/2) = 2.83.", "topic": "Chemistry – Gaseous State"}, {"q": "The ratio of rates of effusion of H2 to CO2 is:", "options": ["22", "2.35", "4.69", "0.21"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(44/2) = 4.69.", "topic": "Chemistry – Gaseous State"}, {"q": "In the reaction Zn + CuSO4 → ZnSO4 + Cu, the oxidising agent is:", "options": ["Zn", "ZnSO4", "Cu", "CuSO4"], "answer": 3, "explanation": "Cu²⁺ gains electrons (reduced to Cu), so CuSO4 is the oxidising agent.", "topic": "Chemistry – Redox Reactions"}, {"q": "A long straight wire carries 5 A. The magnetic field at a perpendicular distance 10 cm from it is:", "options": ["40 μT", "5 μT", "20 μT", "10 μT"], "answer": 3, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×5/0.1 = 10 μT.", "topic": "Physics – Magnetism"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 1 M, [B] = 0.5 M, [C] = 1 M. Kc equals:", "options": ["2", "1", "4", "0.5"], "answer": 0, "explanation": "Kc = [C]/([A][B]) = 1/(1×0.5) = 2.", "topic": "Chemistry – Equilibrium"}, {"q": "2 mol of ideal gas at 2 atm and 400 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["32.84 L", "16.42 L", "65.68 L", "131.36 L"], "answer": 0, "explanation": "V = nRT/P = 2×0.0821×400/2 = 32.84 L.", "topic": "Chemistry – Gaseous State"}, {"q": "The spin-only magnetic moment of [Mn(H2O)6]²⁺ (in BM) is:", "options": ["1.73", "4.90", "3.87", "5.92"], "answer": 3, "explanation": "High-spin d⁵: n = 5 ⇒ μ = √(5×7) = √35 ≈ 5.92 BM.", "topic": "Chemistry – Coordination Compounds"}, {"q": "[Ni(CO)4] has tetrahedral geometry and Ni is in oxidation state:", "options": ["0", "−2", "+4", "+2"], "answer": 0, "explanation": "CO is neutral ⇒ Ni(0), d¹⁰, tetrahedral, diamagnetic.", "topic": "Chemistry – Coordination Compounds"}, {"q": "The determinant of [[3, 5], [4, 1]] is:", "options": ["17", "23", "-17", "3"], "answer": 2, "explanation": "det = ad − bc = 3×1 − 5×4 = -17.", "topic": "Maths – Matrices & Determinants"}, {"q": "Which species acts as both oxidising and reducing agent?", "options": ["K2Cr2O7", "H2O2", "KMnO4", "O3"], "answer": 1, "explanation": "O in H2O2 is −1, midway between 0 and −2, so it can be oxidised or reduced.", "topic": "Chemistry – Redox Reactions"}, {"q": "Which set of quantum numbers is NOT allowed?", "options": ["n = 1, l = 0, m = 0", "n = 2, l = 1, m = 0", "n = 3, l = 2, m = −2", "n = 2, l = 2, m = 0"], "answer": 3, "explanation": "l must be less than n; l = 2 is not allowed when n = 2.", "topic": "Chemistry – Atomic Structure"}, {"q": "The pH of a 0.01 M NaOH solution is:", "options": ["16", "2", "3", "12"], "answer": 3, "explanation": "[OH⁻] = 0.01 M ⇒ pOH = 2 ⇒ pH = 14 − 2 = 12.", "topic": "Chemistry – Equilibrium"}, {"q": "If z = 2 + 3i, then |z^3| equals:", "options": ["23.44", "2197", "46.87", "93.74"], "answer": 2, "explanation": "|zⁿ| = |z|ⁿ = (√(2²+3²))ⁿ = 46.87.", "topic": "Maths – Complex Numbers"}, {"q": "A 4 kg mass moves in a circle of radius 2 m with speed 10 m/s. The centripetal force on it is:", "options": ["100 N", "200 N", "20 N", "2000 N"], "answer": 1, "explanation": "Centripetal force F = mv²/r = 4×10²/2 = 200 N.", "topic": "Physics – Circular Motion"}, {"q": "If A = {1, 2, 3}, the number of subsets of A is:", "options": ["8", "9", "6", "7"], "answer": 0, "explanation": "An n-element set has 2ⁿ subsets: 2³ = 8.", "topic": "Maths – Sets & Functions"}, {"q": "The limit of (e^x − 1)/x as x → 0 is:", "options": ["0", "∞", "1", "e"], "answer": 2, "explanation": "Standard limit: lim(x→0)(e^x − 1)/x = 1.", "topic": "Maths – Limits"}, {"q": "The moment of inertia of a solid sphere of mass 3 kg and radius 1 m about its central axis is (2MR²/5):", "options": ["0.6 kg·m²", "3 kg·m²", "2.4 kg·m²", "1.2 kg·m²"], "answer": 3, "explanation": "I = 2MR²/5 = 231²/5 = 1.2 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The maximum value of y = −4x² + 2x is:", "options": ["0.5", "0.25", "0.12", "1.25"], "answer": 1, "explanation": "Vertex at x = −B/(2A) = 2/(2×4) = 0.25; y_max = 0.25.", "topic": "Maths – Applications of Derivatives"}, {"q": "2 mol of an ideal gas expands isothermally at 300 K from V to 3V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["2740.16 J", "5480.32 J", "2380.07 J", "9976.8 J"], "answer": 1, "explanation": "W = nRT ln(V₂/V₁) = 2×8.314×300×ln3 = 5480.32 J.", "topic": "Physics – Thermodynamics"}, {"q": "A 220 V, 968 W-rated bulb has resistance 50 Ω. The power it consumes at 220 V is:", "options": ["968 W", "1936 W", "484 W", "968 W × 2"], "answer": 0, "explanation": "P = V²/R = 220²/50 = 968 W.", "topic": "Physics – Current Electricity"}, {"q": "The 6th term of the GP 3, 9, 27, … is:", "options": ["2187", "729", "243", "54"], "answer": 1, "explanation": "Tₙ = arⁿ⁻¹ = 3×3ⁿ⁻¹ (n=6) = 729.", "topic": "Maths – Sequences & Series"}, {"q": "If A is a 3×3 matrix with det(A) = 2, then det(2A) equals:", "options": ["6", "4", "16", "8"], "answer": 2, "explanation": "det(kA) = kⁿ·det(A) for n×n A: 2³×2 = 16.", "topic": "Maths – Matrices & Determinants"}, {"q": "If a = (1, 1, 0) and b = (1, 1, 0), then a·b equals:", "options": ["2 × 2", "3", "2", "1"], "answer": 2, "explanation": "a·b = 1×1 + 1×1 = 2.", "topic": "Maths – Vectors"}, {"q": "The moment of inertia of a hollow sphere of mass 2 kg and radius 2 m about its central axis is (2MR²/3):", "options": ["8 kg·m²", "5.33 kg·m²", "2.67 kg·m²", "10.67 kg·m²"], "answer": 1, "explanation": "I = 2MR²/3 = 222²/3 = 5.33 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "An engine exerts a constant force of 500 N to keep a vehicle moving at 20 m/s. The power delivered is:", "options": ["5000 W", "10000 W", "20000 W", "15000 W"], "answer": 1, "explanation": "P = F·v = 500×20 = 10000 W.", "topic": "Physics – Work, Energy & Power"}, {"q": "A simple pendulum of length 0.25 m oscillates with small amplitude (g = 10 m/s²). Its time period is:", "options": ["0.5 s", "0.99 s", "1.4 s", "1.99 s"], "answer": 1, "explanation": "T = 2π√(l/g) = 2π√(0.25/10) = 0.99 s.", "topic": "Physics – Oscillations"}, {"q": "The sum of all binomial coefficients in (1 + x)^5 is:", "options": ["25", "10", "15", "32"], "answer": 3, "explanation": "Put x = 1: sum = (1+1)ⁿ = 2ⁿ = 32.", "topic": "Maths – Binomial Theorem"}, {"q": "The most abundant metal in Earth's crust is:", "options": ["Al", "Fe", "Ca", "Na"], "answer": 0, "explanation": "Aluminium (~8%) is the most abundant metal in the crust.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "A wire experiences a stress of 1×10⁸ N/m² and a strain of 0.01. Its Young's modulus is:", "options": ["40 GPa", "10 GPa", "20 GPa", "0.1 GPa"], "answer": 2, "explanation": "Y = stress/strain = 100000000/0.01 = 20000000000 Pa = 20 GPa.", "topic": "Physics – Elasticity"}, {"q": "The wavelength of the photon emitted in the hydrogen transition n = 3 → 1 lies in the:", "options": ["ultraviolet region", "infrared region", "microwave region", "visible region"], "answer": 0, "explanation": "λ = 1240/ΔE nm ≈ 102.6 nm — the Lyman series.", "topic": "Chemistry – Atomic Structure"}, {"q": "The probability that a leap year has 53 Sundays is:", "options": ["1/7", "3/7", "2/7", "53/366"], "answer": 2, "explanation": "A leap year has 366 days = 52 weeks + 2 extra days; P(both extra days include a Sunday) = 2/7.", "topic": "Maths – Probability"}, {"q": "In NaCl, each Na⁺ is surrounded by how many Cl⁻ ions?", "options": ["8", "6", "4", "12"], "answer": 1, "explanation": "Rock-salt structure: octahedral coordination, each ion has 6 nearest neighbours.", "topic": "Chemistry – Solid State"}, {"q": "A coil of 100 turns has its flux changed by 0.04 Wb in 0.02 s. The magnitude of induced emf is:", "options": ["100 V", "200 V", "2 V", "4 V"], "answer": 1, "explanation": "|ε| = NΔΦ/Δt = 100×0.04/0.02 = 200 V.", "topic": "Physics – EMI & AC"}, {"q": "The most electronegative element is:", "options": ["O", "F", "N", "Cl"], "answer": 1, "explanation": "Electronegativity increases across a period and decreases down a group; F tops the scale at 4.0.", "topic": "Chemistry – Periodic Table"}, {"q": "First ionization energy is generally highest for:", "options": ["K", "He", "Li", "Na"], "answer": 1, "explanation": "Ionization energy decreases down a group and increases across a period; He (noble gas, small) is highest among these.", "topic": "Chemistry – Periodic Table"}, {"q": "If n(A) = 2 and n(B) = 3, the number of relations from A to B is:", "options": ["6", "8", "10", "64"], "answer": 3, "explanation": "Relations = subsets of A×B: 2^(n(A)·n(B)) = 2^6 = 64.", "topic": "Maths – Sets & Functions"}, {"q": "For a normal distribution, mean = median = mode is located at the:", "options": ["cannot be determined", "right tail", "centre of symmetry", "left tail"], "answer": 2, "explanation": "A normal curve is symmetric; mean = median = mode at the centre.", "topic": "Maths – Statistics"}, {"q": "For a cell with E° = 0.8 V, n = 2 and reaction quotient Q = 0.1, the cell emf at 298 K is:", "options": ["0.83 V", "0.77 V", "0.8 V", "0.41 V"], "answer": 0, "explanation": "Nernst: E = E° − (0.0591/n)logQ = 0.8 − (0.0591/2)log(0.1) = 0.83 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "A first-order reaction has k = 0.0231 s⁻¹. Its half-life (in s) is:", "options": ["30 s", "60 s", "15 s", "31 s"], "answer": 0, "explanation": "t½ = 0.693/k = 0.693/0.0231 ≈ 30 s.", "topic": "Chemistry – Chemical Kinetics (numerical)"}, {"q": "The number of terms in the expansion of (x + y)^5 is:", "options": ["10", "7", "6", "5"], "answer": 2, "explanation": "(x + y)ⁿ expands to n + 1 = 6 terms.", "topic": "Maths – Binomial Theorem"}, {"q": "The hybridization of boron in BF3 is:", "options": ["sp", "sp³d", "sp²", "sp³"], "answer": 2, "explanation": "BF3 has 3 bond pairs, no lone pairs → trigonal planar, sp².", "topic": "Chemistry – Chemical Bonding"}, {"q": "A buffer has [salt]/[acid] = 2 and pKa = 9.25. Its pH is:", "options": ["8.55", "10.55", "9.25", "9.55"], "answer": 3, "explanation": "pH = pKa + log([salt]/[acid]) = 9.25 + log(2) = 9.55.", "topic": "Chemistry – Equilibrium"}, {"q": "If Earth's radius were 4 times larger with the same mass, surface gravity would be:", "options": ["g/16", "g/4", "g", "4g"], "answer": 0, "explanation": "g = GM/R² ∝ 1/R² ⇒ g' = g/4² = g/16.", "topic": "Physics – Gravitation"}, {"q": "A 10 kg block on a horizontal surface has coefficient of static friction 0.2. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["10 N", "20 N", "100 N", "2 N"], "answer": 1, "explanation": "Limiting friction f = μN = μ(mg) = 0.2×10×10 = 20 N.", "topic": "Physics – Laws of Motion"}, {"q": "Two 2 μF capacitors are connected in parallel. The equivalent capacitance is:", "options": ["2 μF", "4 μF", "3 μF", "1 μF"], "answer": 1, "explanation": "Parallel: C = 2 + 2 = 4 μF.", "topic": "Physics – Capacitors"}, {"q": "The determinant of [[1, 5], [1, 1]] is:", "options": ["-4", "6", "4", "1"], "answer": 0, "explanation": "det = ad − bc = 1×1 − 5×1 = -4.", "topic": "Maths – Matrices & Determinants"}, {"q": "The gauge pressure at depth 20 m in a liquid of density 800 kg/m³ is (g = 10 m/s²):", "options": ["640 kPa", "80 kPa", "320 kPa", "160 kPa"], "answer": 3, "explanation": "P = ρgh = 800×10×20 = 160000 Pa = 160 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "A potentiometer is preferred over a voltmeter for measuring emf because:", "options": ["it draws no current from the cell", "it is more portable", "it has higher resistance", "it is cheaper"], "answer": 0, "explanation": "At null point no current flows through the cell, so it measures true emf, not terminal voltage.", "topic": "Physics – Current Electricity"}, {"q": "A wave of frequency 500 Hz has wavelength 0.5 m. Its speed is:", "options": ["1000 m/s", "125 m/s", "500 m/s", "250 m/s"], "answer": 3, "explanation": "v = fλ = 500×0.5 = 250 m/s.", "topic": "Physics – Waves"}, {"q": "∫ e^x dx equals:", "options": ["e^x + C", "1 + C", "xe^x + C", "e^(2x)/2 + C"], "answer": 0, "explanation": "The exponential is its own antiderivative: ∫ e^x dx = e^x + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "If det[[4, 1], [2, 3]] = x, then x equals:", "options": ["10", "20", "5", "11"], "answer": 0, "explanation": "x = 4×3 − 1×2 = 10.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "∫ cos(3x) dx equals:", "options": ["sin(3x)/3 + C", "−sin(3x)/3 + C", "sin(3x) + C", "3sin(3x) + C"], "answer": 0, "explanation": "Substitute u = 3x: ∫ cos(3x)dx = sin(3x)/3 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "250 mL of 0.5 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.25 M × 2", "0.25 M", "0.5 M", "0.12 M"], "answer": 1, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 0.5×250/500 = 0.25 M.", "topic": "Chemistry – Solutions"}, {"q": "∫₋ₐ^a x³ dx (a > 0) equals:", "options": ["a⁴/4", "2a⁴", "0", "a⁴/2"], "answer": 2, "explanation": "x³ is an odd function over a symmetric interval, so the integral is 0.", "topic": "Maths – Definite Integrals"}, {"q": "The centre and radius of x² + y² − 4x − 4y + -1 = 0 are:", "options": ["(2, 2), 3", "(-2, -2), 3", "(2, 2), 6", "(4, 4), 3"], "answer": 0, "explanation": "Centre = (−g, −f) = (2, 2); radius = √(g² + f² − c) = 3.", "topic": "Maths – Circles"}, {"q": "Which of the following is the dimensional formula of surface tension is?", "options": ["[MT⁻²]", "[ML²T⁻²]", "[MLT⁻²]", "[MT⁻¹]"], "answer": 0, "explanation": "Surface tension = force/length gives [MLT⁻²]/[L] = [MT⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The middle term in the expansion of (1 + x)^6 is:", "options": ["20x^3", "15x^3", "20x^4", "6x^3"], "answer": 0, "explanation": "n = 6 (even): middle term is T_(4) = C(6,3)x^3 = 20x^3.", "topic": "Maths – Binomial Theorem"}, {"q": "The sum of the first 20 terms of the AP 1, 3, … is:", "options": ["400", "800", "440", "200"], "answer": 0, "explanation": "Sₙ = n/2×[2a + (n−1)d] = 20/2×[2 + 19×2] = 400.", "topic": "Maths – Sequences & Series"}, {"q": "The moment of inertia of a uniform rod about its centre of mass 2 kg and radius 1 m about its central axis is (ML²/12):", "options": ["0.17 kg·m²", "0.08 kg·m²", "2 kg·m²", "0.33 kg·m²"], "answer": 0, "explanation": "I = ML²/12 = 2L²/12 = 0.17 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "A car moving at 20 m/s brakes with deceleration μg where μ = 0.5 (g = 10 m/s²). The stopping distance is (in m):", "options": ["40 m", "80 m", "20 m", "41 m"], "answer": 0, "explanation": "v² = u² − 2as with a = μg: s = 20²/(2×0.5×10) = 40 m.", "topic": "Physics – Kinematics (numerical)"}, {"q": "Which has the largest atomic radius?", "options": ["Li", "Na", "K", "Cs"], "answer": 3, "explanation": "Atomic radius increases down a group; Cs is the largest of these alkali metals.", "topic": "Chemistry – Periodic Table"}, {"q": "A 4 kg block rests on a smooth incline of 30°. The component of its weight parallel to the incline is (g = 10 m/s²):", "options": ["20 N", "40 N", "34.64 N", "10 N"], "answer": 0, "explanation": "Parallel component = mg sinθ = 4×10×sin30° = 20 N.", "topic": "Physics – Laws of Motion"}, {"q": "The energy of an electron in the n = 3 orbit of a hydrogen atom is:", "options": ["-1.51 eV", "-3.02 eV", "1.51 eV", "-0.76 eV"], "answer": 0, "explanation": "Eₙ = −13.6/n² = −13.6/3² = -1.51 eV.", "topic": "Physics – Modern Physics"}, {"q": "A 10 kg block on a horizontal surface has coefficient of static friction 0.5. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["100 N", "50 N", "5 N", "25 N"], "answer": 1, "explanation": "Limiting friction f = μN = μ(mg) = 0.5×10×10 = 50 N.", "topic": "Physics – Laws of Motion"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 0.5 M, [B] = 0.5 M, [C] = 2 M. Kc equals:", "options": ["4", "8", "16", "0.12"], "answer": 1, "explanation": "Kc = [C]/([A][B]) = 2/(0.5×0.5) = 8.", "topic": "Chemistry – Equilibrium"}, {"q": "The critical angle for a glass–air interface with refractive index 1.5 is approximately:", "options": ["20.9°", "41.8°", "83.6°", "48.2°"], "answer": 1, "explanation": "sin C = 1/n = 1/1.5 ⇒ C ≈ 41.8°.", "topic": "Physics – Ray Optics"}, {"q": "The number of atoms per unit cell in a body-centred cubic (BCC) lattice is:", "options": ["2", "1", "4", "6"], "answer": 0, "explanation": "8 corners × 1/8 + 1 body centre = 2 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The volume occupied by 1 mol of an ideal gas at 2 atm and 300 K is (R = 0.0821 L·atm/mol·K):", "options": ["6.16 L", "12.32 L", "24.63 L", "49.26 L"], "answer": 1, "explanation": "V = nRT/P = 1×0.0821×300/2 = 12.32 L.", "topic": "Chemistry – Gaseous State"}, {"q": "The terminal velocity of a small sphere falling in a viscous liquid is proportional to:", "options": ["independent of radius", "the cube of its radius", "the square of its radius", "its radius"], "answer": 2, "explanation": "Stokes' law: v_t = 2r²g(ρ − σ)/(9η) ∝ r².", "topic": "Physics – Fluid Mechanics"}, {"q": "The magnitude of vector (1, 2, 2) is:", "options": ["1.5", "3", "6", "5"], "answer": 1, "explanation": "|v| = √(1² + 2² + 2²) = √9 = 3.", "topic": "Maths – Vectors"}, {"q": "For a reaction, ΔH = 150 kJ/mol and ΔS = 100 J/mol·K at 500 K. The reaction is:", "options": ["non-spontaneous", "endothermic and reversible", "spontaneous", "at equilibrium"], "answer": 0, "explanation": "ΔG = ΔH − TΔS = 150 − 500×0.1 = 100 kJ/mol; negative ΔG ⇒ non-spontaneous.", "topic": "Chemistry – Thermodynamics"}, {"q": "If sin x = 1/2, then cos²x equals:", "options": ["0.75", "0.25", "1", "1.25"], "answer": 0, "explanation": "cos²x = 1 − sin²x = 1 − 1/2² = 0.75.", "topic": "Maths – Trigonometry"}, {"q": "SN1 reactivity order is:", "options": ["1° > 2° > 3°", "2° > 3° > 1°", "3° > 2° > 1°", "3° > 1° > 2°"], "answer": 2, "explanation": "SN1 rate depends on carbocation stability: 3° > 2° > 1°.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The number of molecules in 3 mol of CO2 is:", "options": ["6.022×10²³", "3×6.022×10²³", "3×6.022×10²²", "1806600000000000014680064 atoms"], "answer": 1, "explanation": "Molecules = n × NA = 3 × 6.022×10²³.", "topic": "Chemistry – Mole Concept"}, {"q": "The magnitude of vector (2, 2, 2) is:", "options": ["3.46", "6", "6.93", "1.73"], "answer": 0, "explanation": "|v| = √(2² + 2² + 2²) = √12 = 3.46.", "topic": "Maths – Vectors"}, {"q": "The eccentricity of the ellipse x²/25 + y²/16 = 1 is:", "options": ["5/3", "4/5", "1/2", "3/5"], "answer": 3, "explanation": "a² = 25, b² = 16: e = √(1 − b²/a²) = √(1 − 16/25) = 3/5.", "topic": "Maths – Conic Sections"}, {"q": "Two resistors of 2 Ω each are joined in parallel. The equivalent resistance is:", "options": ["2 Ω", "4 Ω", "3 Ω", "1 Ω"], "answer": 3, "explanation": "Parallel: 1/R = 1/2 + 1/2 ⇒ R = 1 Ω.", "topic": "Physics – Current Electricity"}, {"q": "If α and β are roots of x² − 7x + 8 = 0, then α² + β² equals:", "options": ["16", "65", "33", "41"], "answer": 2, "explanation": "α² + β² = (α+β)² − 2αβ = 7² − 2×8 = 33.", "topic": "Maths – Quadratic Equations"}, {"q": "The distance between (1, 1, 3) and (2, 1, 3) is:", "options": ["1 × 2", "2", "3", "1"], "answer": 3, "explanation": "d = √(Δx² + Δy² + Δz²) = 1.", "topic": "Maths – 3D Geometry"}, {"q": "The mean of the data 2, 5, 7, 9, 4 is:", "options": ["5.4", "27", "6.4", "4.4"], "answer": 0, "explanation": "Mean = sum/n = 27/5 = 5.4.", "topic": "Maths – Statistics"}, {"q": "The general solution of dy/dx = 2x is:", "options": ["y = 2x + C", "y = x² + C", "y = x²/2 + C", "y = 2"], "answer": 1, "explanation": "Integrate: y = ∫ 2x dx = x² + C.", "topic": "Maths – Differential Equations"}, {"q": "The oxidation number of Mn in KMnO4 is:", "options": ["+4", "+2", "+6", "+7"], "answer": 3, "explanation": "+1 + x + 4(−2) = 0 ⇒ x = +7.", "topic": "Chemistry – Redox Reactions"}, {"q": "The derivative of sin(4x) with respect to x is:", "options": ["4cos(4x)", "−4cos(4x)", "cos(4x)", "4sin(4x)"], "answer": 0, "explanation": "Chain rule: d/dx[sin(4x)] = 4cos(4x).", "topic": "Maths – Differentiation"}, {"q": "The density of N2 at STP (M = 28 g/mol) is approximately:", "options": ["0.62 g/L", "1.25 g/L", "2.5 g/L", "1.25 g/L × 2"], "answer": 1, "explanation": "d = PM/(RT) = 1×28/(0.0821×273) = 1.25 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "Compared to an electron moving with the same momentum, a proton's de Broglie wavelength is:", "options": ["1836 times larger", "1836 times smaller", "the same", "zero"], "answer": 2, "explanation": "λ = h/p depends only on momentum, which is the same for both.", "topic": "Physics – Modern Physics"}, {"q": "Mass of zinc deposited by 3 A for 96.5 min (Zn²⁺ + 2e⁻ → Zn, M = 65.4) is:", "options": ["11.77 g", "0.18 g", "5.89 g", "2.94 g"], "answer": 2, "explanation": "m = ItM/(nF) = 3×5790×65.4/(2×96500) = 5.89 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The sum of all binomial coefficients in (1 + x)^6 is:", "options": ["12", "21", "64", "36"], "answer": 2, "explanation": "Put x = 1: sum = (1+1)ⁿ = 2ⁿ = 64.", "topic": "Maths – Binomial Theorem"}, {"q": "Light of photon energy 5 eV falls on a metal of work function 2 eV. The maximum kinetic energy of emitted electrons is:", "options": ["7 eV", "10 eV", "-3 eV", "3 eV"], "answer": 3, "explanation": "K_max = hν − φ = 5 − 2 = 3 eV.", "topic": "Physics – Modern Physics"}, {"q": "The pH of a 0 M HCl solution is:", "options": ["2", "11", "4", "3"], "answer": 3, "explanation": "HCl is a strong acid: [H⁺] = 0 M ⇒ pH = −log0 = 3.", "topic": "Chemistry – Equilibrium"}, {"q": "Two 6 μF capacitors are connected in parallel. The equivalent capacitance is:", "options": ["9 μF", "12 μF", "3 μF", "6 μF"], "answer": 1, "explanation": "Parallel: C = 6 + 6 = 12 μF.", "topic": "Physics – Capacitors"}, {"q": "H2O has a bent shape due to:", "options": ["2 lone pairs on oxygen", "hydrogen bonding", "sp hybridization", "polar bonds only"], "answer": 0, "explanation": "Two lone pairs compress the tetrahedral angle to ~104.5°.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The mean of the data 6, 8, 4, 3, 6 is:", "options": ["6.4", "5.4", "27", "4.4"], "answer": 1, "explanation": "Mean = sum/n = 27/5 = 5.4.", "topic": "Maths – Statistics"}, {"q": "A transformer has 100 primary and 400 secondary turns. With 110 V applied to the primary, the secondary voltage is:", "options": ["110 V", "220 V", "440 V", "27.5 V"], "answer": 2, "explanation": "V₂/V₁ = N₂/N₁ ⇒ V₂ = 110×400/100 = 440 V.", "topic": "Physics – EMI & AC"}, {"q": "The derivative of e^(2x) with respect to x is:", "options": ["e^(x)", "e^(2x)", "2e^(2x)", "2xe^(2x)"], "answer": 2, "explanation": "Chain rule: d/dx[e^(2x)] = 2e^(2x).", "topic": "Maths – Differentiation"}, {"q": "The volume occupied by 1 mol of an ideal gas at 1 atm and 300 K is (R = 0.0821 L·atm/mol·K):", "options": ["24.63 L", "12.32 L", "24.63 L × 2", "49.26 L"], "answer": 0, "explanation": "V = nRT/P = 1×0.0821×300/1 = 24.63 L.", "topic": "Chemistry – Gaseous State"}, {"q": "A 2 μF capacitor is charged to 500 V. The energy stored in it is:", "options": ["0.25 J", "0.5 J", "0.12 J", "0.25 J × 2"], "answer": 0, "explanation": "U = ½CV² = ½×2×10⁻⁶×500² = 0.25 J.", "topic": "Physics – Capacitors"}, {"q": "Two vectors of magnitudes 4 and 5 units act at 60° to each other. The magnitude of their resultant is:", "options": ["1 units", "7.81 units", "6.4 units", "9 units"], "answer": 1, "explanation": "R = √(A² + B² + 2ABcosθ) = √(4²+5²+2×4×5×cos60°) = 7.81 units.", "topic": "Physics – Vectors"}, {"q": "A 4 μF capacitor is charged to 500 V. The energy stored in it is:", "options": ["0.5 J × 2", "1 J", "0.5 J", "0.25 J"], "answer": 2, "explanation": "U = ½CV² = ½×4×10⁻⁶×500² = 0.5 J.", "topic": "Physics – Capacitors"}, {"q": "The number of atoms per unit cell in a face-centred cubic (FCC) lattice is:", "options": ["6", "4", "2", "1"], "answer": 1, "explanation": "8 corners × 1/8 + 6 faces × 1/2 = 4 atoms.", "topic": "Chemistry – Solid State"}, {"q": "The wavelength of the photon emitted in the hydrogen transition n = 4 → 1 lies in the:", "options": ["visible region", "microwave region", "ultraviolet region", "infrared region"], "answer": 2, "explanation": "λ = 1240/ΔE nm ≈ 97.3 nm — the Lyman series.", "topic": "Chemistry – Atomic Structure"}, {"q": "The solution of dy/dx = ky (k = 3) with y(0) = 1 is:", "options": ["y = 3x + 1", "y = e^x + 3", "y = e^(3x)", "y = 3e^x"], "answer": 2, "explanation": "dy/y = 3dx ⇒ ln y = 3x + C; y(0) = 1 gives y = e^(3x).", "topic": "Maths – Differential Equations"}, {"q": "[CoF6]³⁻ is paramagnetic with 4 unpaired electrons because F⁻ is a:", "options": ["strong field ligand", "weak field ligand", "ambidentate ligand", "chelating ligand"], "answer": 1, "explanation": "Weak field F⁻ gives high-spin d⁶ Co(III): t2g⁴ eg², 4 unpaired electrons.", "topic": "Chemistry – Coordination Compounds"}, {"q": "An object is placed 60 cm in front of a concave mirror of focal length 20 cm. The image distance is:", "options": ["40 cm", "15 cm", "30 cm", "30 cm × 2"], "answer": 2, "explanation": "1/v = 1/f − 1/u = 1/20 − 1/60 ⇒ v = 30 cm (real, inverted).", "topic": "Physics – Ray Optics"}, {"q": "The gauge pressure at depth 20 m in a liquid of density 1000 kg/m³ is (g = 10 m/s²):", "options": ["200 kPa", "400 kPa", "800 kPa", "100 kPa"], "answer": 0, "explanation": "P = ρgh = 1000×10×20 = 200000 Pa = 200 kPa.", "topic": "Physics – Fluid Mechanics"}, {"q": "If z = 3i, then z² + 3² equals:", "options": ["0", "18", "3", "-18"], "answer": 0, "explanation": "z² = (3i)² = −3², so z² + 3² = 0.", "topic": "Maths – Complex Numbers"}, {"q": "Mass of copper deposited by 5 A for 30 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["5.92 g", "0.09 g", "2.96 g", "1.48 g"], "answer": 2, "explanation": "m = ItM/(nF) = 5×1800×63.5/(2×96500) = 2.96 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The shape of PCl5 is:", "options": ["octahedral", "trigonal bipyramidal", "square pyramidal", "tetrahedral"], "answer": 1, "explanation": "PCl5 has 5 bond pairs → trigonal bipyramidal.", "topic": "Chemistry – Chemical Bonding"}, {"q": "If α and β are roots of x² − 6x + 8 = 0, then α² + β² equals:", "options": ["52", "10", "20", "28"], "answer": 2, "explanation": "α² + β² = (α+β)² − 2αβ = 6² − 2×8 = 20.", "topic": "Maths – Quadratic Equations"}, {"q": "If P(A) = 1/3 and P(B) = 1/4 are mutually exclusive, P(A ∪ B) equals:", "options": ["1/2", "1/7", "1/12", "7/12"], "answer": 3, "explanation": "Mutually exclusive: P(A∪B) = P(A) + P(B) = 1/3 + 1/4 = 7/12.", "topic": "Maths – Probability"}, {"q": "The element with the highest second electron affinity (most endothermic) trend belongs to:", "options": ["Te", "O", "S", "Se"], "answer": 1, "explanation": "Adding a second electron to O⁻ is strongly endothermic due to repulsion; the value is positive (energy absorbed).", "topic": "Chemistry – Periodic Table"}, {"q": "The energy of an electron in the n = 2 orbit of a hydrogen atom is:", "options": ["-6.8 eV", "-3.4 eV", "-1.7 eV", "3.4 eV"], "answer": 1, "explanation": "Eₙ = −13.6/n² = −13.6/2² = -3.4 eV.", "topic": "Physics – Modern Physics"}, {"q": "If Earth's radius were 2 times larger with the same mass, surface gravity would be:", "options": ["g/2", "2g", "g/4", "g"], "answer": 2, "explanation": "g = GM/R² ∝ 1/R² ⇒ g' = g/2² = g/4.", "topic": "Physics – Gravitation"}, {"q": "The number of moles in 58.5 g of NaCl (molar mass 58.5 g/mol) is:", "options": ["3422.25 mol", "1 mol", "2 mol", "0.5 mol"], "answer": 1, "explanation": "n = mass/molar mass = 58.5/58.5 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The moment of inertia of a solid disc of mass 2 kg and radius 0.5 m about its central axis is (MR²/2):", "options": ["0.5 kg·m²", "0.12 kg·m²", "0.25 kg·m² × 2", "0.25 kg·m²"], "answer": 3, "explanation": "I = MR²/2 = 20.5²/2 = 0.25 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "A wave of frequency 500 Hz has wavelength 2 m. Its speed is:", "options": ["500 m/s", "250 m/s", "1000 m/s", "2000 m/s"], "answer": 2, "explanation": "v = fλ = 500×2 = 1000 m/s.", "topic": "Physics – Waves"}, {"q": "In CsCl, the coordination number of each ion is:", "options": ["12", "8", "6", "4"], "answer": 1, "explanation": "CsCl: simple cubic Cl⁻ with Cs⁺ at the body centre → 8:8 coordination.", "topic": "Chemistry – Solid State"}, {"q": "If the absolute temperature of a gas is increased 4-fold, its rms molecular speed becomes:", "options": ["unchanged", "4 times", "4² times", "√4 times"], "answer": 3, "explanation": "v_rms = √(3RT/M) ∝ √T ⇒ increases by √4.", "topic": "Physics – Kinetic Theory"}, {"q": "If z = 2 + 3i, then |z^4| equals:", "options": ["338", "84.5", "169", "28561"], "answer": 2, "explanation": "|zⁿ| = |z|ⁿ = (√(2²+3²))ⁿ = 169.", "topic": "Maths – Complex Numbers"}, {"q": "A wave of frequency 50 Hz has wavelength 1 m. Its speed is:", "options": ["50 m/s × 2", "50 m/s", "100 m/s", "25 m/s"], "answer": 1, "explanation": "v = fλ = 50×1 = 50 m/s.", "topic": "Physics – Waves"}, {"q": "The centre and radius of x² + y² − 4x − 2y + -4 = 0 are:", "options": ["(2, 1), 6", "(2, 1), 3", "(4, 2), 3", "(-2, -1), 3"], "answer": 1, "explanation": "Centre = (−g, −f) = (2, 1); radius = √(g² + f² − c) = 3.", "topic": "Maths – Circles"}, {"q": "If α and β are roots of x² − 5x + 6 = 0, then α² + β² equals:", "options": ["6", "13", "37", "19"], "answer": 1, "explanation": "α² + β² = (α+β)² − 2αβ = 5² − 2×6 = 13.", "topic": "Maths – Quadratic Equations"}, {"q": "The solution of dy/dx = ky (k = 2) with y(0) = 1 is:", "options": ["y = 2x + 1", "y = e^x + 2", "y = e^(2x)", "y = 2e^x"], "answer": 2, "explanation": "dy/y = 2dx ⇒ ln y = 2x + C; y(0) = 1 gives y = e^(2x).", "topic": "Maths – Differential Equations"}, {"q": "The value of ∫₀^1 x^1 dx is:", "options": ["1", "0.25", "0.5", "0.5 × 2"], "answer": 2, "explanation": "[x^2/2]₀^1 = 1^2/2 = 0.5.", "topic": "Maths – Definite Integrals"}, {"q": "Which of the following is the dimensional formula of the gas constant R is?", "options": ["[ML²T⁻¹K⁻¹]", "[ML²T⁻²K⁻²]", "[ML²T⁻²K⁻¹]", "[MLT⁻²K⁻¹]"], "answer": 2, "explanation": "R = PV/(nT) gives [ML²T⁻²]/[K] per mole = [ML²T⁻²K⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "3 mol of ideal gas at 2 atm and 400 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["98.52 L", "197.04 L", "24.63 L", "49.26 L"], "answer": 3, "explanation": "V = nRT/P = 3×0.0821×400/2 = 49.26 L.", "topic": "Chemistry – Gaseous State"}, {"q": "An electron is accelerated through 100 V. Its de Broglie wavelength is approximately:", "options": ["0.12 nm", "12 nm", "1.2 nm", "0.012 nm"], "answer": 0, "explanation": "λ = h/√p(2meV) ≈ 1.227/√V nm = 1.227/10 ≈ 0.12 nm.", "topic": "Physics – Modern Physics"}, {"q": "A system absorbs 200 J of heat and does 60 J of work on the surroundings. The change in internal energy is:", "options": ["140 J", "260 J", "-140 J", "200 J"], "answer": 0, "explanation": "First law: ΔU = q − w (work done BY system) = 200 − 60 = 140 J.", "topic": "Chemistry – Thermodynamics"}, {"q": "The focus of the parabola y² = 12x is:", "options": ["(6, 0)", "(3, 0)", "(-3, 0)", "(0, 3)"], "answer": 1, "explanation": "y² = 4ax → focus at (a, 0) = (3, 0).", "topic": "Maths – Conic Sections"}, {"q": "The distance between (3, 2, 2) and (4, 4, 4) is:", "options": ["6", "4", "3", "2"], "answer": 2, "explanation": "d = √(Δx² + Δy² + Δz²) = 3.", "topic": "Maths – 3D Geometry"}, {"q": "The period of sin(3x) is:", "options": ["2π", "π/3", "2π/3", "π"], "answer": 2, "explanation": "Period of sin(kx) is 2π/k = 2π/3.", "topic": "Maths – Trigonometry"}, {"q": "An engine exerts a constant force of 100 N to keep a vehicle moving at 20 m/s. The power delivered is:", "options": ["1000 W", "4000 W", "3000 W", "2000 W"], "answer": 3, "explanation": "P = F·v = 100×20 = 2000 W.", "topic": "Physics – Work, Energy & Power"}, {"q": "The distance between (1, 1, 3) and (3, 1, 3) is:", "options": ["2", "1", "3", "4"], "answer": 0, "explanation": "d = √(Δx² + Δy² + Δz²) = 2.", "topic": "Maths – 3D Geometry"}, {"q": "The rms speed of oxygen molecules at 300 K (M = 32 g/mol) is approximately:", "options": ["240 m/s", "483 m/s", "960 m/s", "1200 m/s"], "answer": 1, "explanation": "v_rms = √(3RT/M) = √(3×8.314×300/0.032) ≈ 483 m/s.", "topic": "Physics – Kinetic Theory"}, {"q": "The distance between (2, 2, 2) and (4, 4, 4) is:", "options": ["3.46", "2.46", "4.46", "6.93"], "answer": 0, "explanation": "d = √(Δx² + Δy² + Δz²) = 3.46.", "topic": "Maths – 3D Geometry"}, {"q": "The number of σ and π bonds in ethyne (C2H2) is:", "options": ["5σ, 0π", "3σ, 2π", "2σ, 3π", "3σ, 1π"], "answer": 1, "explanation": "C≡C: 1σ + 2π between carbons, plus 2 C–H σ = 3σ, 2π.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The distance between (2, 0, 0) and (5, 2, 2) is:", "options": ["5.12", "4.12", "8.25", "3.12"], "answer": 1, "explanation": "d = √(Δx² + Δy² + Δz²) = 4.12.", "topic": "Maths – 3D Geometry"}, {"q": "Two tuning forks of frequencies 440 Hz and 442 Hz are sounded together. The beat frequency heard is:", "options": ["4 Hz", "1 Hz", "2 Hz", "442 Hz"], "answer": 2, "explanation": "Beat frequency = |f₁ − f₂| = 2 Hz.", "topic": "Physics – Waves"}, {"q": "The shape of SF4 is:", "options": ["trigonal bipyramidal", "tetrahedral", "see-saw", "square planar"], "answer": 2, "explanation": "SF4 has 4 bond pairs + 1 lone pair → see-saw geometry.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A car moving at 10 m/s brakes with deceleration μg where μ = 0.2 (g = 10 m/s²). The stopping distance is (in m):", "options": ["25 m", "50 m", "12.5 m", "26 m"], "answer": 0, "explanation": "v² = u² − 2as with a = μg: s = 10²/(2×0.2×10) = 25 m.", "topic": "Physics – Kinematics (numerical)"}, {"q": "If z = 1 + 3i, then |z^4| equals:", "options": ["10000", "100", "50", "200"], "answer": 1, "explanation": "|zⁿ| = |z|ⁿ = (√(1²+3²))ⁿ = 100.", "topic": "Maths – Complex Numbers"}, {"q": "The limit of (x^2 − 3^2)/(x − 3) as x → 3 is:", "options": ["3", "12", "6", "9"], "answer": 2, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 2×3ⁿ⁻¹ = 6.", "topic": "Maths – Limits"}, {"q": "At a height 3R above Earth's surface (R = Earth's radius), the acceleration due to gravity is (g at surface):", "options": ["g/4", "g/16", "g", "g/64"], "answer": 1, "explanation": "g_h = g(R/(R+h))² = g/(1+3)² = g/16.", "topic": "Physics – Gravitation"}, {"q": "The 5th term of the GP 2, 4, 8, … is:", "options": ["64", "20", "32", "16"], "answer": 2, "explanation": "Tₙ = arⁿ⁻¹ = 2×2ⁿ⁻¹ (n=5) = 32.", "topic": "Maths – Sequences & Series"}, {"q": "cos²x + sin²x equals:", "options": ["2", "0", "1", "cos 2x"], "answer": 2, "explanation": "The fundamental Pythagorean identity: cos²x + sin²x = 1.", "topic": "Maths – Trigonometry"}, {"q": "A particle starts from rest and moves with constant acceleration 2 m/s². Its speed after travelling 25 m is:", "options": ["20 m/s", "10 m/s", "5 m/s", "10 m/s × 2"], "answer": 1, "explanation": "Use v² = u² + 2as with u = 0: v = √(2×2×25) = 10 m/s.", "topic": "Physics – Kinematics"}, {"q": "A long straight wire carries 2 A. The magnetic field at a perpendicular distance 10 cm from it is:", "options": ["4 μT", "8 μT", "16 μT", "2 μT"], "answer": 0, "explanation": "B = μ₀I/(2πr) = 2×10⁻⁷×2/0.1 = 4 μT.", "topic": "Physics – Magnetism"}, {"q": "For a gaseous reaction with Δn_g = 2, the relation between Kp and Kc is:", "options": ["Kp = Kc(RT)^-2", "Kp = Kc(RT)^2", "Kc = Kp(RT)^2", "Kp = Kc"], "answer": 1, "explanation": "Kp = Kc(RT)^Δn_g = Kc(RT)^2.", "topic": "Chemistry – Equilibrium"}, {"q": "In an LCR series circuit, L = 10 mH and C = 10 μF. The resonant frequency is:", "options": ["251.65 Hz", "160.2 Hz", "1006.58 Hz", "503.29 Hz"], "answer": 3, "explanation": "f₀ = 1/(2π√(LC)) = 1/(2π√(0.01×0)) = 503.29 Hz.", "topic": "Physics – EMI & AC"}, {"q": "A radioactive sample has half-life 2 h. The fraction remaining after 6 h is:", "options": ["0.12", "0.25", "0.06", "1.12"], "answer": 0, "explanation": "Fraction = (1/2)^(t/T) = (1/2)^3 = 0.12.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "A simple pendulum of length 2.5 m oscillates with small amplitude (g = 10 m/s²). Its time period is:", "options": ["6.28 s", "4.44 s", "3.14 s", "1.57 s"], "answer": 2, "explanation": "T = 2π√(l/g) = 2π√(2.5/10) = 3.14 s.", "topic": "Physics – Oscillations"}, {"q": "The freezing point depression of a 1 molal aqueous solution of NaCl (van't Hoff factor i = 3, Kf = 1.86 K·kg/mol) is:", "options": ["2.79 K", "11.16 K", "1.86 K", "5.58 K"], "answer": 3, "explanation": "ΔTf = i·Kf·m = 3×1.86×1 = 5.58 K.", "topic": "Chemistry – Solutions"}, {"q": "The determinant of [[4, 1], [1, 1]] is:", "options": ["-3", "3", "5", "4"], "answer": 1, "explanation": "det = ad − bc = 4×1 − 1×1 = 3.", "topic": "Maths – Matrices & Determinants"}, {"q": "3 mol of ideal gas at 1 atm and 300 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["73.89 L × 2", "36.95 L", "73.89 L", "147.78 L"], "answer": 2, "explanation": "V = nRT/P = 3×0.0821×300/1 = 73.89 L.", "topic": "Chemistry – Gaseous State"}, {"q": "Two vectors are perpendicular if and only if their dot product is:", "options": ["equal to the product of magnitudes", "0", "1", "−1"], "answer": 1, "explanation": "a·b = |a||b|cosθ = 0 when θ = 90°.", "topic": "Maths – Vectors"}, {"q": "∫ 3x^4 dx equals:", "options": ["3x^5 + C", "12x^3 + C", "0.6x^4 + C", "0.6x^5 + C"], "answer": 3, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 3x^5/5 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "For a gaseous reaction with Δn_g = -1, the relation between Kp and Kc is:", "options": ["Kc = Kp(RT)^-1", "Kp = Kc(RT)^-1", "Kp = Kc", "Kp = Kc(RT)^1"], "answer": 1, "explanation": "Kp = Kc(RT)^Δn_g = Kc(RT)^-1.", "topic": "Chemistry – Equilibrium"}, {"q": "The oxidation number of P in H3PO4 is:", "options": ["+1", "+3", "+5", "+7"], "answer": 2, "explanation": "3(+1) + x + 4(−2) = 0 ⇒ x = +5.", "topic": "Chemistry – Redox Reactions"}, {"q": "250 mL of 1 M NaOH is diluted to 1000 mL. The molarity of the diluted solution is:", "options": ["0.12 M", "1 M", "0.5 M", "0.25 M"], "answer": 3, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 1×250/1000 = 0.25 M.", "topic": "Chemistry – Solutions"}, {"q": "For an ideal gas, Cp − Cv equals:", "options": ["0", "R", "γR", "2R"], "answer": 1, "explanation": "Mayer's relation: Cp − Cv = R per mole of ideal gas.", "topic": "Chemistry – Thermodynamics"}, {"q": "Light of photon energy 5 eV falls on a metal of work function 1 eV. The maximum kinetic energy of emitted electrons is:", "options": ["-4 eV", "6 eV", "5 eV", "4 eV"], "answer": 3, "explanation": "K_max = hν − φ = 5 − 1 = 4 eV.", "topic": "Physics – Modern Physics"}, {"q": "250 mL of 2 M NaOH is diluted to 1000 mL. The molarity of the diluted solution is:", "options": ["2 M", "0.25 M", "1 M", "0.5 M"], "answer": 3, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 2×250/1000 = 0.5 M.", "topic": "Chemistry – Solutions"}, {"q": "A wire experiences a stress of 2×10⁸ N/m² and a strain of 0.01. Its Young's modulus is:", "options": ["20 GPa", "80 GPa", "40 GPa", "0.2 GPa"], "answer": 2, "explanation": "Y = stress/strain = 200000000/0.01 = 40000000000 Pa = 40 GPa.", "topic": "Physics – Elasticity"}, {"q": "Mass of copper deposited by 1 A for 60 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["1.18 g", "0.59 g", "2.37 g", "0.04 g"], "answer": 0, "explanation": "m = ItM/(nF) = 1×3600×63.5/(2×96500) = 1.18 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "∫ 2x^3 dx equals:", "options": ["2x^4 + C", "0.5x^4 + C", "6x^2 + C", "0.5x^3 + C"], "answer": 1, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 2x^4/4 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The critical angle for a glass–air interface with refractive index 2.0 is approximately:", "options": ["30°", "15°", "60°", "30° × 2"], "answer": 0, "explanation": "sin C = 1/n = 1/2.0 ⇒ C ≈ 30°.", "topic": "Physics – Ray Optics"}, {"q": "1 mol of an ideal gas expands isothermally at 300 K from V to 2V. The work done by the gas is (R = 8.314 J/mol·K):", "options": ["1728.85 J", "750.83 J", "2494.2 J", "864.42 J"], "answer": 0, "explanation": "W = nRT ln(V₂/V₁) = 1×8.314×300×ln2 = 1728.85 J.", "topic": "Physics – Thermodynamics"}, {"q": "Two vectors of magnitudes 5 and 6 units act at 60° to each other. The magnitude of their resultant is:", "options": ["11 units", "1 units", "7.81 units", "9.54 units"], "answer": 3, "explanation": "R = √(A² + B² + 2ABcosθ) = √(5²+6²+2×5×6×cos60°) = 9.54 units.", "topic": "Physics – Vectors"}, {"q": "Mass of nickel deposited by 2 A for 96.5 min (Ni²⁺ + 2e⁻ → Ni, M = 58.7) is:", "options": ["7.04 g", "1.76 g", "0.12 g", "3.52 g"], "answer": 3, "explanation": "m = ItM/(nF) = 2×5790×58.7/(2×96500) = 3.52 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The minimum value of x + 1/x for x > 0 is:", "options": ["2", "0", "1", "∞"], "answer": 0, "explanation": "By AM ≥ GM, x + 1/x ≥ 2√(x·1/x) = 2, equality at x = 1.", "topic": "Maths – Applications of Derivatives"}, {"q": "If |z| = 1, then z·z̅ equals:", "options": ["1", "0", "2", "z²"], "answer": 0, "explanation": "z·z̅ = |z|² = 1.", "topic": "Maths – Complex Numbers"}, {"q": "A convex lens has focal length 50 cm (magnitude). Its power is:", "options": ["2 D", "0.5 D", "-2 D", "0.02 D"], "answer": 0, "explanation": "P = 100/f(cm) = 2 = 2 D.", "topic": "Physics – Ray Optics"}, {"q": "The 20th term of the AP 3, 7, 11, … is:", "options": ["75", "83", "79", "79 × 2"], "answer": 2, "explanation": "Tₙ = a + (n−1)d = 3 + 19×4 = 79.", "topic": "Maths – Sequences & Series"}, {"q": "The derivative of sin(2x) with respect to x is:", "options": ["cos(2x)", "2cos(2x)", "−2cos(2x)", "2sin(2x)"], "answer": 1, "explanation": "Chain rule: d/dx[sin(2x)] = 2cos(2x).", "topic": "Maths – Differentiation"}, {"q": "A wire of length 1 m and cross-section 1 mm² is stretched by 1 mm under a force of 200 N. The elastic potential energy stored is:", "options": ["0.05 J", "0.2 J", "0.1 J × 2", "0.1 J"], "answer": 3, "explanation": "U = ½ × force × extension = ½×200×0 = 0.1 J.", "topic": "Physics – Elasticity"}, {"q": "The middle term in the expansion of (1 + x)^8 is:", "options": ["56x^4", "70x^5", "70x^4", "8x^4"], "answer": 2, "explanation": "n = 8 (even): middle term is T_(5) = C(8,4)x^4 = 70x^4.", "topic": "Maths – Binomial Theorem"}, {"q": "Two point charges 2 μC and 3 μC are 0.2 m apart in vacuum. The electrostatic force between them is:", "options": ["0.13 N", "13.5 N", "0.67 N", "1.35 N"], "answer": 3, "explanation": "F = kq₁q₂/r² = 9×10⁹×2×3×10⁻¹²/0.2² = 1.35 N.", "topic": "Physics – Electrostatics"}, {"q": "A simple pendulum of length 1 m oscillates with small amplitude (g = 10 m/s²). Its time period is:", "options": ["3.97 s", "1.99 s", "0.99 s", "2.81 s"], "answer": 1, "explanation": "T = 2π√(l/g) = 2π√(1/10) = 1.99 s.", "topic": "Physics – Oscillations"}, {"q": "A wire of length 2 m and cross-section 2 mm² is stretched by 2 mm under a force of 200 N. The elastic potential energy stored is:", "options": ["0.4 J", "0.1 J", "0.2 J × 2", "0.2 J"], "answer": 3, "explanation": "U = ½ × force × extension = ½×200×0 = 0.2 J.", "topic": "Physics – Elasticity"}, {"q": "250 mL of 1 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.5 M", "1 M", "0.5 M × 2", "0.25 M"], "answer": 0, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 1×250/500 = 0.5 M.", "topic": "Chemistry – Solutions"}, {"q": "The solubility of Ag2CrO4-type salt MX2 is s = 0.00001 mol/L. Its Ksp is:", "options": ["0.000000000000001", "0.0000000001", "0.000000000000004", "0.000000000000002"], "answer": 2, "explanation": "MX2 ⇌ M²⁺ + 2X⁻: Ksp = [M²⁺][X⁻]² = s×(2s)² = 4s³ = 0.000000000000004.", "topic": "Chemistry – Equilibrium"}, {"q": "The bond order of CO is:", "options": ["3.5", "2.5", "3", "4"], "answer": 2, "explanation": "Bond order = (bonding − antibonding electrons)/2; for CO this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 1 M, [B] = 2 M, [C] = 1 M. Kc equals:", "options": ["0.5", "0.25", "1", "2"], "answer": 0, "explanation": "Kc = [C]/([A][B]) = 1/(1×2) = 0.5.", "topic": "Chemistry – Equilibrium"}, {"q": "If α and β are roots of x² − 7x + 10 = 0, then α² + β² equals:", "options": ["14", "39", "69", "29"], "answer": 3, "explanation": "α² + β² = (α+β)² − 2αβ = 7² − 2×10 = 29.", "topic": "Maths – Quadratic Equations"}, {"q": "An electron (charge 1.6×10⁻¹⁹ C) enters a magnetic field of 2 T perpendicularly with speed 1×10⁶ m/s. The magnetic force on it is:", "options": ["0 N × 3", "0 N", "0 N × 4", "0 N × 2"], "answer": 1, "explanation": "F = qvB sin90° = 1.6×10⁻¹⁹×1×10⁶×2 = 0 N.", "topic": "Physics – Magnetism"}, {"q": "The middle term in the expansion of (1 + x)^10 is:", "options": ["10x^5", "210x^5", "252x^5", "252x^6"], "answer": 2, "explanation": "n = 10 (even): middle term is T_(6) = C(10,5)x^5 = 252x^5.", "topic": "Maths – Binomial Theorem"}, {"q": "Washing soda is:", "options": ["Na2CO3·10H2O", "NaHCO3", "NaOH", "Na2CO3 (anhydrous)"], "answer": 0, "explanation": "Washing soda is sodium carbonate decahydrate.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "If y = 2x^5, then dy/dx equals:", "options": ["10x^5", "10x^6", "10x^4", "2x^4"], "answer": 2, "explanation": "dy/dx = 2×5x^4 = 10x^4.", "topic": "Maths – Differentiation"}, {"q": "The quadratic equation with roots 2 and 1 is:", "options": ["x² − 3x + 2 = 0", "x² − 3x − 2 = 0", "x² + 3x + 2 = 0", "x² + 2x − 3 = 0"], "answer": 0, "explanation": "x² − (sum)x + (product) = 0 ⇒ x² − 3x + 2 = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "The focus of the parabola y² = 16x is:", "options": ["(0, 4)", "(8, 0)", "(4, 0)", "(-4, 0)"], "answer": 2, "explanation": "y² = 4ax → focus at (a, 0) = (4, 0).", "topic": "Maths – Conic Sections"}, {"q": "The value of sin 30° + cos 60° is:", "options": ["√3/2", "1", "0", "1/2"], "answer": 1, "explanation": "sin 30° = 1/2 and cos 60° = 1/2, so the sum is 1.", "topic": "Maths – Trigonometry"}, {"q": "In a BCC unit cell, the relation between edge length a and atomic radius r is:", "options": ["a = 4r", "a = 2r", "√3·a = 4r", "√2·a = 4r"], "answer": 2, "explanation": "Body diagonal = √3·a = 4r in BCC.", "topic": "Chemistry – Solid State"}, {"q": "The ratio of the radius of the n = 3 orbit to the n = 2 orbit of hydrogen is:", "options": ["2.25", "1.5", "3.38", "0.44"], "answer": 0, "explanation": "r ∝ n², so r₂/r₁ = (3/2)² = 2.25.", "topic": "Physics – Modern Physics"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 5 to n = 1 is:", "options": ["13.06 eV", "6.53 eV", "-13.06 eV", "26.11 eV"], "answer": 0, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/1² − 1/5²) = 13.06 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "The freezing point depression of a 1 molal aqueous solution of NaCl (van't Hoff factor i = 1, Kf = 1.86 K·kg/mol) is:", "options": ["0.93 K", "3.72 K", "1.86 K × 2", "1.86 K"], "answer": 3, "explanation": "ΔTf = i·Kf·m = 1×1.86×1 = 1.86 K.", "topic": "Chemistry – Solutions"}, {"q": "A first-order reaction has rate constant k = 0.0693 min⁻¹. Its half-life is:", "options": ["10 min", "20 min", "5 min", "14.43 min"], "answer": 0, "explanation": "First order: t½ = 0.693/k = 0.693/0.0693 = 10 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "Bleaching powder is:", "options": ["NaOCl", "CaCl2", "Ca(OCl)2", "CaOCl2"], "answer": 3, "explanation": "Bleaching powder: CaOCl2 (calcium oxychloride).", "topic": "Chemistry – s, p, d & f Block"}, {"q": "The focal length of a lens depends on all of the following EXCEPT:", "options": ["refractive index of the material", "the object distance", "wavelength of light used", "radii of curvature"], "answer": 1, "explanation": "Lensmaker's formula 1/f = (μ−1)(1/R₁ − 1/R₂) involves μ, R₁, R₂ — not object distance.", "topic": "Physics – Ray Optics"}, {"q": "Two 6 μF capacitors are connected in series. The equivalent capacitance is:", "options": ["12 μF", "6 μF", "4 μF", "3 μF"], "answer": 3, "explanation": "Series: 1/C = 1/6 + 1/6 ⇒ C = 3 μF.", "topic": "Physics – Capacitors"}, {"q": "The slope of the line y = 3x + 4 is:", "options": ["0.3333333333333333", "3", "4", "-3"], "answer": 1, "explanation": "In y = mx + c, the slope is m = 3.", "topic": "Maths – Straight Lines"}, {"q": "EDTA is a:", "options": ["bidentate ligand", "hexadentate ligand", "monodentate ligand", "tridentate ligand"], "answer": 1, "explanation": "EDTA donates through 2 N and 4 O atoms → hexadentate.", "topic": "Chemistry – Coordination Compounds"}, {"q": "A transformer has 100 primary and 400 secondary turns. With 220 V applied to the primary, the secondary voltage is:", "options": ["440 V", "880 V", "220 V", "55 V"], "answer": 1, "explanation": "V₂/V₁ = N₂/N₁ ⇒ V₂ = 220×400/100 = 880 V.", "topic": "Physics – EMI & AC"}, {"q": "A 5 μF capacitor is charged to 100 V. The energy stored in it is:", "options": ["0.03 J × 2", "0.05 J", "0.01 J", "0.03 J"], "answer": 3, "explanation": "U = ½CV² = ½×5×10⁻⁶×100² = 0.03 J.", "topic": "Physics – Capacitors"}, {"q": "A spring of force constant 400 N/m is stretched by 0.1 m. The elastic potential energy stored is:", "options": ["1 J", "4 J", "40 J", "2 J"], "answer": 3, "explanation": "U = ½kx² = ½×400×0.1² = 2 J.", "topic": "Physics – Work, Energy & Power"}, {"q": "Given A → B, ΔH = -100 kJ/mol and B → C, ΔH = -150 kJ/mol, ΔH for A → C is:", "options": ["250 kJ/mol", "-125 kJ/mol", "50 kJ/mol", "-250 kJ/mol"], "answer": 3, "explanation": "Hess's law: ΔH = -100 + (-150) = -250 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "A ball is projected with velocity 20 m/s at 30° above the horizontal. The maximum height reached is (g = 10 m/s²):", "options": ["2.5 m", "5 m", "10 m", "20 m"], "answer": 1, "explanation": "H = u²sin²θ/(2g) = 20²×sin²30°/20 = 5 m.", "topic": "Physics – Projectile Motion"}, {"q": "Which of the following is the dimensional formula of Planck's constant is?", "options": ["[ML²T⁻²]", "[MLT⁻¹]", "[ML³T⁻¹]", "[ML²T⁻¹]"], "answer": 3, "explanation": "h = E/ν gives [ML²T⁻²]/[T⁻¹] = [ML²T⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "Given A → B, ΔH = -50 kJ/mol and B → C, ΔH = -100 kJ/mol, ΔH for A → C is:", "options": ["50 kJ/mol", "-150 kJ/mol", "150 kJ/mol", "-75 kJ/mol"], "answer": 1, "explanation": "Hess's law: ΔH = -50 + (-100) = -150 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "Mass of copper deposited by 2 A for 96.5 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["7.62 g", "0.12 g", "1.91 g", "3.81 g"], "answer": 3, "explanation": "m = ItM/(nF) = 2×5790×63.5/(2×96500) = 3.81 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The volume occupied by 2 mol of an ideal gas at 1 atm and 300 K is (R = 0.0821 L·atm/mol·K):", "options": ["49.26 L", "24.63 L", "49.26 L × 2", "98.52 L"], "answer": 0, "explanation": "V = nRT/P = 2×0.0821×300/1 = 49.26 L.", "topic": "Chemistry – Gaseous State"}, {"q": "Two vectors of magnitudes 5 and 3 units act at 0° to each other. The magnitude of their resultant is:", "options": ["2 units", "5.83 units", "8 units", "8 units × 2"], "answer": 2, "explanation": "R = √(A² + B² + 2ABcosθ) = √(5²+3²+2×5×3×cos0°) = 8 units.", "topic": "Physics – Vectors"}, {"q": "The centre and radius of x² + y² − 6x − 4y + 9 = 0 are:", "options": ["(3, 2), 2", "(3, 2), 4", "(6, 4), 2", "(-3, -2), 2"], "answer": 0, "explanation": "Centre = (−g, −f) = (3, 2); radius = √(g² + f² − c) = 2.", "topic": "Maths – Circles"}, {"q": "The length of the latus rectum of y² = 8x is:", "options": ["2", "4", "16", "8"], "answer": 3, "explanation": "For y² = 4ax, latus rectum = 4a = 8.", "topic": "Maths – Conic Sections"}, {"q": "If z = 2i, then z² + 2² equals:", "options": ["2", "8", "-8", "0"], "answer": 3, "explanation": "z² = (2i)² = −2², so z² + 2² = 0.", "topic": "Maths – Complex Numbers"}, {"q": "For l = 3, the number of orbitals is:", "options": ["5", "9", "3", "7"], "answer": 3, "explanation": "Number of orbitals = 2l + 1 = 7 (f subshell).", "topic": "Chemistry – Atomic Structure"}, {"q": "A Carnot engine operates between 500 K and 200 K. Its efficiency is:", "options": ["30%", "-150%", "60%", "40%"], "answer": 2, "explanation": "η = 1 − T₂/T₁ = 1 − 200/500 = 60%.", "topic": "Physics – Thermodynamics"}, {"q": "The sum to infinity of the GP 4, 1.33, 0.44, … is:", "options": ["3", "6", "12", "6 × 2"], "answer": 1, "explanation": "S∞ = a/(1 − r) with r = 1/3: 4/(1 − 1/3) = 6.", "topic": "Maths – Sequences & Series"}, {"q": "A 4 kg mass moves in a circle of radius 5 m with speed 5 m/s. The centripetal force on it is:", "options": ["4 N", "20 N", "100 N", "10 N"], "answer": 1, "explanation": "Centripetal force F = mv²/r = 4×5²/5 = 20 N.", "topic": "Physics – Circular Motion"}, {"q": "The number of unpaired electrons in [Fe(CN)6]³⁻ is:", "options": ["3", "0", "1", "5"], "answer": 2, "explanation": "Strong field CN⁻: low-spin d⁵ → t2g⁵, one unpaired electron.", "topic": "Chemistry – Coordination Compounds"}, {"q": "sin(2x) equals:", "options": ["cos²x − sin²x only", "2 sin²x", "sin²x + cos²x", "2 sin x cos x"], "answer": 3, "explanation": "Double-angle formula: sin 2x = 2 sin x cos x.", "topic": "Maths – Trigonometry"}, {"q": "The IUPAC name of K3[Fe(CN)6] is:", "options": ["potassium hexacyanidoferrate(III)", "tripotassium hexacyanidoferrate(III)", "potassium hexacyanoferrate(II)", "potassium hexacyanide ferrate(III)"], "answer": 0, "explanation": "Anionic complex: hexacyanido + ferrate; Fe is +3.", "topic": "Chemistry – Coordination Compounds"}, {"q": "Which ion is smallest?", "options": ["Ne", "Na⁺", "Mg²⁺", "Al³⁺"], "answer": 3, "explanation": "Among isoelectronic species, the one with the most protons (Al³⁺) is smallest.", "topic": "Chemistry – Periodic Table"}, {"q": "If z = 3 + 1i, then |z^2| equals:", "options": ["5", "20", "10", "100"], "answer": 2, "explanation": "|zⁿ| = |z|ⁿ = (√(3²+1²))ⁿ = 10.", "topic": "Maths – Complex Numbers"}, {"q": "The number of moles in 120 g of urea CO(NH2)2 (molar mass 60 g/mol) is:", "options": ["7200 mol", "1 mol", "2 mol", "4 mol"], "answer": 2, "explanation": "n = mass/molar mass = 120/60 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The centre and radius of x² + y² − 2x − 2y + -7 = 0 are:", "options": ["(1, 1), 6", "(1, 1), 3", "(-1, -1), 3", "(2, 2), 3"], "answer": 1, "explanation": "Centre = (−g, −f) = (1, 1); radius = √(g² + f² − c) = 3.", "topic": "Maths – Circles"}, {"q": "The freezing point depression of a 2 molal aqueous solution of NaCl (van't Hoff factor i = 3, Kf = 1.86 K·kg/mol) is:", "options": ["5.58 K", "11.16 K", "3.72 K", "22.32 K"], "answer": 1, "explanation": "ΔTf = i·Kf·m = 3×1.86×2 = 11.16 K.", "topic": "Chemistry – Solutions"}, {"q": "An ice cube floating in water melts completely. The water level:", "options": ["rises", "falls", "first rises then falls", "remains unchanged"], "answer": 3, "explanation": "The floating ice displaces water equal to its own weight; melted water exactly fills that volume.", "topic": "Physics – Fluid Mechanics"}, {"q": "Acidity order: HCOOH, CH3COOH, ClCH2COOH is:", "options": ["HCOOH > ClCH2COOH > CH3COOH", "ClCH2COOH > HCOOH > CH3COOH", "all equal", "CH3COOH > HCOOH > ClCH2COOH"], "answer": 1, "explanation": "–I of Cl strengthens the acid; +I of CH3 weakens it relative to formic acid.", "topic": "Chemistry – Organic Chemistry"}, {"q": "An object is placed 40 cm in front of a concave mirror of focal length 10 cm. The image distance is:", "options": ["13.33 cm", "8 cm", "13.33 cm × 2", "20 cm"], "answer": 0, "explanation": "1/v = 1/f − 1/u = 1/10 − 1/40 ⇒ v = 13.33 cm (real, inverted).", "topic": "Physics – Ray Optics"}, {"q": "The bond order of O2 is:", "options": ["3", "1.5", "2.5", "2"], "answer": 3, "explanation": "Bond order = (bonding − antibonding electrons)/2; for O2 this equals 2.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A mass of 0.5 kg attached to a spring of constant 100 N/m oscillates. Its time period is:", "options": ["0.89 s", "0.44 s × 2", "0.44 s", "0.22 s"], "answer": 2, "explanation": "T = 2π√(m/k) = 2π√(0.5/100) = 0.44 s.", "topic": "Physics – Oscillations"}, {"q": "A buffer has [salt]/[acid] = 2 and pKa = 4.76. Its pH is:", "options": ["6.06", "5.06", "4.76", "4.06"], "answer": 1, "explanation": "pH = pKa + log([salt]/[acid]) = 4.76 + log(2) = 5.06.", "topic": "Chemistry – Equilibrium"}, {"q": "The maximum value of y = −2x² + 2x is:", "options": ["1", "0.25", "1.5", "0.5"], "answer": 3, "explanation": "Vertex at x = −B/(2A) = 2/(2×2) = 0.5; y_max = 0.5.", "topic": "Maths – Applications of Derivatives"}, {"q": "Two resistors of 4 Ω each are joined in series. The equivalent resistance is:", "options": ["8 Ω", "2 Ω", "4 Ω", "6 Ω"], "answer": 0, "explanation": "Series: R = 4 + 4 = 8 Ω.", "topic": "Physics – Current Electricity"}, {"q": "A square matrix A satisfies A² = A. Such a matrix is called:", "options": ["orthogonal", "idempotent", "nilpotent", "involutory"], "answer": 1, "explanation": "A² = A defines an idempotent matrix (A² = 0 is nilpotent, A² = I is involutory).", "topic": "Maths – Matrices & Determinants"}, {"q": "The directrix of the parabola y² = 8x is:", "options": ["x = −2", "y = 2", "x = 2", "y = −2"], "answer": 0, "explanation": "y² = 4ax with 4a = 8 ⇒ a = 2; directrix x = −a = −2.", "topic": "Maths – Conic Sections"}, {"q": "A 100 V, 500 W-rated bulb has resistance 20 Ω. The power it consumes at 100 V is:", "options": ["250 W", "500 W", "500 W × 2", "1000 W"], "answer": 1, "explanation": "P = V²/R = 100²/20 = 500 W.", "topic": "Physics – Current Electricity"}, {"q": "∫ 3x^2 dx equals:", "options": ["6x^1 + C", "1x^2 + C", "1x^3 + C", "3x^3 + C"], "answer": 2, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 3x^3/3 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "Esterification of a carboxylic acid with an alcohol needs:", "options": ["conc. H2SO4 catalyst", "no catalyst", "NaOH catalyst", "Pt catalyst"], "answer": 0, "explanation": "Fischer esterification is acid-catalysed.", "topic": "Chemistry – Organic Chemistry"}, {"q": "The limit of (1 + 5/x)^x as x → ∞ is:", "options": ["1", "e", "5e", "e^5"], "answer": 3, "explanation": "lim(x→∞)(1 + 5/x)^x = e^5.", "topic": "Maths – Limits"}, {"q": "A projectile is fired with speed 10 m/s at 45° to the horizontal (g = 10 m/s²). Its horizontal range is:", "options": ["10 m", "14.14 m", "5 m", "20 m"], "answer": 0, "explanation": "Range R = u²sin2θ/g; at 45°, sin2θ = 1, so R = 10²/10 = 10 m.", "topic": "Physics – Projectile Motion"}, {"q": "The magnitude of vector (3, 4, 2) is:", "options": ["5.39", "9", "10.77", "2.69"], "answer": 0, "explanation": "|v| = √(3² + 4² + 2²) = √29 = 5.39.", "topic": "Maths – Vectors"}, {"q": "A car moving at 20 m/s brakes with deceleration μg where μ = 0.2 (g = 10 m/s²). The stopping distance is (in m):", "options": ["100 m", "200 m", "50 m", "101 m"], "answer": 0, "explanation": "v² = u² − 2as with a = μg: s = 20²/(2×0.2×10) = 100 m.", "topic": "Physics – Kinematics (numerical)"}, {"q": "The 20th term of the AP 3, 6, 9, … is:", "options": ["60 × 2", "57", "63", "60"], "answer": 3, "explanation": "Tₙ = a + (n−1)d = 3 + 19×3 = 60.", "topic": "Maths – Sequences & Series"}, {"q": "The determinant of [[4, 5], [4, 5]] is:", "options": ["40", "0", "20", "0 × 2"], "answer": 1, "explanation": "det = ad − bc = 4×5 − 5×4 = 0.", "topic": "Maths – Matrices & Determinants"}, {"q": "A wave of frequency 100 Hz has wavelength 1 m. Its speed is:", "options": ["100 m/s × 2", "200 m/s", "50 m/s", "100 m/s"], "answer": 3, "explanation": "v = fλ = 100×1 = 100 m/s.", "topic": "Physics – Waves"}, {"q": "The magnitude of vector (3, 2, 2) is:", "options": ["7", "4.12", "2.06", "8.25"], "answer": 1, "explanation": "|v| = √(3² + 2² + 2²) = √17 = 4.12.", "topic": "Maths – Vectors"}, {"q": "Kepler's third law states that for planetary orbits:", "options": ["T ∝ r²", "T² ∝ r²", "T² ∝ r³", "T ∝ r³"], "answer": 2, "explanation": "Kepler's third law: the square of the orbital period is proportional to the cube of the semi-major axis.", "topic": "Physics – Gravitation"}, {"q": "The area under y = x from x = 0 to x = 3 (in sq. units) is:", "options": ["4.5 sq units", "9 sq units", "2.25 sq units", "5.5 sq units"], "answer": 0, "explanation": "Area = ∫₀^3 x dx = 3²/2 = 4.5.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "2 mol of ideal gas at 1 atm and 400 K occupies (R = 0.0821 L·atm/mol·K):", "options": ["131.36 L", "65.68 L × 2", "65.68 L", "32.84 L"], "answer": 2, "explanation": "V = nRT/P = 2×0.0821×400/1 = 65.68 L.", "topic": "Chemistry – Gaseous State"}, {"q": "The energy of the photon emitted when an electron in hydrogen drops from n = 3 to n = 1 is:", "options": ["6.04 eV", "-12.09 eV", "24.18 eV", "12.09 eV"], "answer": 3, "explanation": "ΔE = 13.6(1/n₁² − 1/n₂²) = 13.6(1/1² − 1/3²) = 12.09 eV.", "topic": "Chemistry – Atomic Structure"}, {"q": "The value of C(6, 3) is:", "options": ["21", "120", "19", "20"], "answer": 3, "explanation": "C(6,3) = 6!/(3!(6−3)!) = 20.", "topic": "Maths – Permutations & Combinations"}, {"q": "A particle starts from rest and moves with constant acceleration 10 m/s². Its speed after travelling 20 m is:", "options": ["10 m/s", "40 m/s", "20 m/s", "20 m/s × 2"], "answer": 2, "explanation": "Use v² = u² + 2as with u = 0: v = √(2×10×20) = 20 m/s.", "topic": "Physics – Kinematics"}, {"q": "NaCl has which type of crystal structure?", "options": ["simple cubic", "HCP", "BCC", "FCC (rock salt)"], "answer": 3, "explanation": "NaCl: Cl⁻ forms FCC with Na⁺ in all octahedral voids — rock-salt structure.", "topic": "Chemistry – Solid State"}, {"q": "The determinant of [[1, 1], [2, 5]] is:", "options": ["5", "3", "7", "-3"], "answer": 1, "explanation": "det = ad − bc = 1×5 − 1×2 = 3.", "topic": "Maths – Matrices & Determinants"}, {"q": "Mass of silver deposited by 1 A for 120 min (Ag⁺ + e⁻ → Ag, M = 108) is:", "options": ["8.06 g", "4.03 g", "16.12 g", "0.07 g"], "answer": 0, "explanation": "m = ItM/(nF) = 1×7200×108/(1×96500) = 8.06 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "Given A → B, ΔH = -200 kJ/mol and B → C, ΔH = -100 kJ/mol, ΔH for A → C is:", "options": ["300 kJ/mol", "-150 kJ/mol", "-300 kJ/mol", "-100 kJ/mol"], "answer": 2, "explanation": "Hess's law: ΔH = -200 + (-100) = -300 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "A 4 μF capacitor is charged to 100 V. The energy stored in it is:", "options": ["0.02 J", "0.04 J", "0.01 J", "0.02 J × 2"], "answer": 0, "explanation": "U = ½CV² = ½×4×10⁻⁶×100² = 0.02 J.", "topic": "Physics – Capacitors"}, {"q": "The determinant of [[1, 1], [1, 1]] is:", "options": ["2", "0", "1", "0 × 2"], "answer": 1, "explanation": "det = ad − bc = 1×1 − 1×1 = 0.", "topic": "Maths – Matrices & Determinants"}, {"q": "A Carnot engine operates between 400 K and 300 K. Its efficiency is:", "options": ["75%", "12.5%", "25%", "-33.33%"], "answer": 2, "explanation": "η = 1 − T₂/T₁ = 1 − 300/400 = 25%.", "topic": "Physics – Thermodynamics"}, {"q": "A 20 kg block on a horizontal surface has coefficient of static friction 0.2. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["200 N", "20 N", "4 N", "40 N"], "answer": 3, "explanation": "Limiting friction f = μN = μ(mg) = 0.2×20×10 = 40 N.", "topic": "Physics – Laws of Motion"}, {"q": "The number of moles in 360 g of glucose C6H12O6 (molar mass 180 g/mol) is:", "options": ["2 mol", "64800 mol", "4 mol", "1 mol"], "answer": 0, "explanation": "n = mass/molar mass = 360/180 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The slope of the line y = 3x + 2 is:", "options": ["0.3333333333333333", "2", "3", "-3"], "answer": 2, "explanation": "In y = mx + c, the slope is m = 3.", "topic": "Maths – Straight Lines"}, {"q": "Two resistors of 3 Ω each are joined in series. The equivalent resistance is:", "options": ["6 Ω", "4.5 Ω", "1.5 Ω", "3 Ω"], "answer": 0, "explanation": "Series: R = 3 + 3 = 6 Ω.", "topic": "Physics – Current Electricity"}, {"q": "The slope of the line y = 2x + 1 is:", "options": ["1", "-2", "0.5", "2"], "answer": 3, "explanation": "In y = mx + c, the slope is m = 2.", "topic": "Maths – Straight Lines"}, {"q": "The solubility of Ag2CrO4-type salt MX2 is s = 0.00002 mol/L. Its Ksp is:", "options": ["0.000000000000032", "0.000000000000016", "0.0000000004", "0.000000000000008"], "answer": 0, "explanation": "MX2 ⇌ M²⁺ + 2X⁻: Ksp = [M²⁺][X⁻]² = s×(2s)² = 4s³ = 0.000000000000032.", "topic": "Chemistry – Equilibrium"}, {"q": "The value of ∫₀^1 x^2 dx is:", "options": ["0.67", "1", "0.33", "0.17"], "answer": 2, "explanation": "[x^3/3]₀^1 = 1^3/3 = 0.33.", "topic": "Maths – Definite Integrals"}, {"q": "The limit of (1 + 3/x)^x as x → ∞ is:", "options": ["3e", "1", "e^3", "e"], "answer": 2, "explanation": "lim(x→∞)(1 + 3/x)^x = e^3.", "topic": "Maths – Limits"}, {"q": "The value of P(6, 2) is:", "options": ["15", "60", "30 × 2", "30"], "answer": 3, "explanation": "P(6,2) = 6!/(6−2)! = 30.", "topic": "Maths – Permutations & Combinations"}, {"q": "The value of C(8, 3) is:", "options": ["55", "336", "56", "57"], "answer": 2, "explanation": "C(8,3) = 8!/(3!(8−3)!) = 56.", "topic": "Maths – Permutations & Combinations"}, {"q": "The unit of the rate constant for a second-order reaction is:", "options": ["mol·L⁻¹·s⁻¹", "L·mol⁻¹·s⁻¹", "L²·mol⁻²·s⁻¹", "s⁻¹"], "answer": 1, "explanation": "Units of k = (mol/L)^(1−n)·s⁻¹; for n = 2 this is L·mol⁻¹·s⁻¹.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "Total nodes in a 4s orbital:", "options": ["5", "4", "2", "3"], "answer": 3, "explanation": "Total nodes = n − 1 = 3 (all radial for s).", "topic": "Chemistry – Atomic Structure"}, {"q": "If n(A) = 3 and n(B) = 3, the number of relations from A to B is:", "options": ["27", "512", "9", "12"], "answer": 1, "explanation": "Relations = subsets of A×B: 2^(n(A)·n(B)) = 2^9 = 512.", "topic": "Maths – Sets & Functions"}, {"q": "An electron (charge 1.6×10⁻¹⁹ C) enters a magnetic field of 2 T perpendicularly with speed 2×10⁶ m/s. The magnetic force on it is:", "options": ["0 N", "0 N × 3", "0 N × 4", "0 N × 2"], "answer": 0, "explanation": "F = qvB sin90° = 1.6×10⁻¹⁹×2×10⁶×2 = 0 N.", "topic": "Physics – Magnetism"}, {"q": "The distance between (0, 2, 3) and (3, 4, 3) is:", "options": ["2.61", "3.61", "7.21", "4.61"], "answer": 1, "explanation": "d = √(Δx² + Δy² + Δz²) = 3.61.", "topic": "Maths – 3D Geometry"}, {"q": "The nature of the roots of 1x² + 2x + 1 = 0 is:", "options": ["real and equal", "complex (non-real)", "real and equal × 2", "real and distinct"], "answer": 0, "explanation": "D = b² − 4ac = 2² − 4×1×1 = 0; sign of D gives real and equal roots.", "topic": "Maths – Quadratic Equations"}, {"q": "A 20 kg block on a horizontal surface has coefficient of static friction 0.3. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["200 N", "6 N", "30 N", "60 N"], "answer": 3, "explanation": "Limiting friction f = μN = μ(mg) = 0.3×20×10 = 60 N.", "topic": "Physics – Laws of Motion"}, {"q": "If a = (3, 2, 0) and b = (3, 1, 0), then a·b equals:", "options": ["9", "11", "12", "10"], "answer": 1, "explanation": "a·b = 3×3 + 2×1 = 11.", "topic": "Maths – Vectors"}, {"q": "Mass of zinc deposited by 0.5 A for 120 min (Zn²⁺ + 2e⁻ → Zn, M = 65.4) is:", "options": ["0.61 g", "1.22 g", "0.04 g", "2.44 g"], "answer": 1, "explanation": "m = ItM/(nF) = 0.5×7200×65.4/(2×96500) = 1.22 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "The number of moles in 100 g of CaCO3 (molar mass 100 g/mol) is:", "options": ["10000 mol", "1 mol", "0.5 mol", "2 mol"], "answer": 1, "explanation": "n = mass/molar mass = 100/100 = 1 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "A convex lens has focal length 100 cm (magnitude). Its power is:", "options": ["0.01 D", "1 D", "-1 D", "1 D × 2"], "answer": 1, "explanation": "P = 100/f(cm) = 1 = 1 D.", "topic": "Physics – Ray Optics"}, {"q": "The 5th term of the GP 3, 9, 27, … is:", "options": ["81", "243", "729", "45"], "answer": 1, "explanation": "Tₙ = arⁿ⁻¹ = 3×3ⁿ⁻¹ (n=5) = 243.", "topic": "Maths – Sequences & Series"}, {"q": "The electric field at a distance 0.1 m from a point charge of 2 μC is:", "options": ["1800000 N/C", "900000 N/C", "3600000 N/C", "180000 N/C"], "answer": 0, "explanation": "E = kq/r² = 9×10⁹×2×10⁻⁶/0.1² = 1800000 N/C.", "topic": "Physics – Electrostatics"}, {"q": "The mean of the data 8, 4, 7, 4, 5 is:", "options": ["28", "5.6", "6.6", "4.6"], "answer": 1, "explanation": "Mean = sum/n = 28/5 = 5.6.", "topic": "Maths – Statistics"}, {"q": "The centre and radius of x² + y² − 4x − 6y + 9 = 0 are:", "options": ["(4, 6), 2", "(2, 3), 4", "(2, 3), 2", "(-2, -3), 2"], "answer": 2, "explanation": "Centre = (−g, −f) = (2, 3); radius = √(g² + f² − c) = 2.", "topic": "Maths – Circles"}, {"q": "In a Wheatstone bridge, P = 4 Ω, Q = 4 Ω, R = 3 Ω. The unknown resistance S for balance is:", "options": ["3 Ω × 2", "11 Ω", "1.5 Ω", "3 Ω"], "answer": 3, "explanation": "Balance: P/Q = R/S ⇒ S = QR/P = 4×3/4 = 3 Ω.", "topic": "Physics – Current Electricity"}, {"q": "The density of CO2 at STP (M = 44 g/mol) is approximately:", "options": ["0.98 g/L", "1.96 g/L", "1.96 g/L × 2", "3.93 g/L"], "answer": 1, "explanation": "d = PM/(RT) = 1×44/(0.0821×273) = 1.96 g/L.", "topic": "Chemistry – Gaseous State"}, {"q": "The electric field at a distance 0.5 m from a point charge of 2 μC is:", "options": ["72000 N/C × 2", "72000 N/C", "144000 N/C", "36000 N/C"], "answer": 1, "explanation": "E = kq/r² = 9×10⁹×2×10⁻⁶/0.5² = 72000 N/C.", "topic": "Physics – Electrostatics"}, {"q": "Mass of copper deposited by 2 A for 60 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["2.37 g", "0.07 g", "1.18 g", "4.74 g"], "answer": 0, "explanation": "m = ItM/(nF) = 2×3600×63.5/(2×96500) = 2.37 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "A particle starts from rest and moves with constant acceleration 4 m/s². Its speed after travelling 32 m is:", "options": ["8 m/s", "16 m/s × 2", "32 m/s", "16 m/s"], "answer": 3, "explanation": "Use v² = u² + 2as with u = 0: v = √(2×4×32) = 16 m/s.", "topic": "Physics – Kinematics"}, {"q": "If z = 2 + 1i, then |z^4| equals:", "options": ["25", "12.5", "625", "50"], "answer": 0, "explanation": "|zⁿ| = |z|ⁿ = (√(2²+1²))ⁿ = 25.", "topic": "Maths – Complex Numbers"}, {"q": "In an LCR series circuit, L = 10 mH and C = 4 μF. The resonant frequency is:", "options": ["397.89 Hz", "253.3 Hz", "1591.55 Hz", "795.77 Hz"], "answer": 3, "explanation": "f₀ = 1/(2π√(LC)) = 1/(2π√(0.01×0)) = 795.77 Hz.", "topic": "Physics – EMI & AC"}, {"q": "The slope of the line y = -2x + 2 is:", "options": ["-0.5", "-2", "2", "-2 × 2"], "answer": 1, "explanation": "In y = mx + c, the slope is m = -2.", "topic": "Maths – Straight Lines"}, {"q": "Mass of copper deposited by 5 A for 60 min (Cu²⁺ + 2e⁻ → Cu, M = 63.5) is:", "options": ["0.19 g", "5.92 g", "11.84 g", "2.96 g"], "answer": 1, "explanation": "m = ItM/(nF) = 5×3600×63.5/(2×96500) = 5.92 g.", "topic": "Chemistry – Electrochemistry"}, {"q": "Which of the following is the dimensional formula of magnetic field B is?", "options": ["[MT⁻¹A⁻¹]", "[ML²T⁻²A⁻¹]", "[MT⁻²A⁻¹]", "[MLT⁻²A⁻¹]"], "answer": 2, "explanation": "F = qvB gives B = F/(qv) = [MLT⁻²]/([AT][LT⁻¹]) = [MT⁻²A⁻¹].", "topic": "Physics – Units & Dimensions"}, {"q": "Given A → B, ΔH = -50 kJ/mol and B → C, ΔH = -300 kJ/mol, ΔH for A → C is:", "options": ["350 kJ/mol", "-350 kJ/mol", "-175 kJ/mol", "250 kJ/mol"], "answer": 1, "explanation": "Hess's law: ΔH = -50 + (-300) = -350 kJ/mol.", "topic": "Chemistry – Thermodynamics"}, {"q": "The maximum value of y = −3x² + 4x is:", "options": ["2.67", "1.33", "0.67", "2.33"], "answer": 1, "explanation": "Vertex at x = −B/(2A) = 4/(2×3) = 0.67; y_max = 1.33.", "topic": "Maths – Applications of Derivatives"}, {"q": "In an LCR series circuit, L = 10 mH and C = 1 μF. The resonant frequency is:", "options": ["506.61 Hz", "3183.1 Hz", "1591.55 Hz", "795.77 Hz"], "answer": 2, "explanation": "f₀ = 1/(2π√(LC)) = 1/(2π√(0.01×0)) = 1591.55 Hz.", "topic": "Physics – EMI & AC"}, {"q": "For the Al electrode with E° = -1.66 V (n = 3) and ion activity giving Q = 10, the electrode potential at 298 K is:", "options": ["-1.66 V", "-1.64 V", "-1.68 V", "-3.36 V"], "answer": 2, "explanation": "E = E° − (0.0591/n)logQ = -1.66 − (0.0591/3)×log(10) = -1.68 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "The bond order of CN- is:", "options": ["4", "3", "2.5", "3.5"], "answer": 1, "explanation": "Bond order = (bonding − antibonding electrons)/2; for CN- this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "tan 45° equals:", "options": ["1", "0", "√3", "∞"], "answer": 0, "explanation": "tan 45° = sin45°/cos45° = 1.", "topic": "Maths – Trigonometry"}, {"q": "200 mL of 0.5 M NaOH is diluted to 500 mL. The molarity of the diluted solution is:", "options": ["0.4 M", "0.5 M", "0.2 M", "0.1 M"], "answer": 2, "explanation": "M₁V₁ = M₂V₂ ⇒ M₂ = 0.5×200/500 = 0.2 M.", "topic": "Chemistry – Solutions"}, {"q": "The maximum value of y = −4x² + 4x is:", "options": ["2", "1 × 2", "0.5", "1"], "answer": 3, "explanation": "Vertex at x = −B/(2A) = 4/(2×4) = 0.5; y_max = 1.", "topic": "Maths – Applications of Derivatives"}, {"q": "A 4 μF capacitor is charged to 200 V. The energy stored in it is:", "options": ["0.04 J", "0.16 J", "0.08 J × 2", "0.08 J"], "answer": 3, "explanation": "U = ½CV² = ½×4×10⁻⁶×200² = 0.08 J.", "topic": "Physics – Capacitors"}, {"q": "The moment of inertia of a hollow sphere of mass 2 kg and radius 1 m about its central axis is (2MR²/3):", "options": ["2 kg·m²", "2.67 kg·m²", "1.33 kg·m²", "0.67 kg·m²"], "answer": 2, "explanation": "I = 2MR²/3 = 221²/3 = 1.33 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The area under y = x from x = 0 to x = 2 (in sq. units) is:", "options": ["2 sq units", "4 sq units", "1 sq units", "3 sq units"], "answer": 0, "explanation": "Area = ∫₀^2 x dx = 2²/2 = 2.", "topic": "Maths – Definite Integrals (numerical)"}, {"q": "If z = 2 + 2i, then |z^2| equals:", "options": ["64", "8", "16", "4"], "answer": 1, "explanation": "|zⁿ| = |z|ⁿ = (√(2²+2²))ⁿ = 8.", "topic": "Maths – Complex Numbers"}, {"q": "The quadratic equation with roots 3 and 4 is:", "options": ["x² + 12x − 7 = 0", "x² − 7x + 12 = 0", "x² + 7x + 12 = 0", "x² − 7x − 12 = 0"], "answer": 1, "explanation": "x² − (sum)x + (product) = 0 ⇒ x² − 7x + 12 = 0.", "topic": "Maths – Quadratic Equations"}, {"q": "The number of moles in 49 g of H2SO4 (molar mass 98 g/mol) is:", "options": ["0.5 mol", "1 mol", "4802 mol", "0.25 mol"], "answer": 0, "explanation": "n = mass/molar mass = 49/98 = 0.5 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The value of C(5, 3) is:", "options": ["11", "9", "60", "10"], "answer": 3, "explanation": "C(5,3) = 5!/(3!(5−3)!) = 10.", "topic": "Maths – Permutations & Combinations"}, {"q": "Two point charges 1 μC and 4 μC are 0.1 m apart in vacuum. The electrostatic force between them is:", "options": ["0.36 N", "1.8 N", "36 N", "3.6 N"], "answer": 3, "explanation": "F = kq₁q₂/r² = 9×10⁹×1×4×10⁻¹²/0.1² = 3.6 N.", "topic": "Physics – Electrostatics"}, {"q": "The eccentricity of the rectangular hyperbola x² − y² = 25 is:", "options": ["2", "1/√2", "1", "√2"], "answer": 3, "explanation": "For x²/a² − y²/b² = 1 with a = b, e = √(1 + b²/a²) = √2.", "topic": "Maths – Conic Sections"}, {"q": "The moment of inertia of a hollow sphere of mass 3 kg and radius 1 m about its central axis is (2MR²/3):", "options": ["4 kg·m²", "2 kg·m²", "1 kg·m²", "3 kg·m²"], "answer": 1, "explanation": "I = 2MR²/3 = 231²/3 = 2 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "If y = x·e^x, then dy/dx equals:", "options": ["(1 + x)", "e^x", "e^x(1 + x)", "xe^x"], "answer": 2, "explanation": "Product rule: dy/dx = e^x + xe^x = e^x(1 + x).", "topic": "Maths – Differentiation"}, {"q": "A 5 kg block on a horizontal surface has coefficient of static friction 0.2. The maximum horizontal force before it slips is (g = 10 m/s²):", "options": ["1 N", "5 N", "50 N", "10 N"], "answer": 3, "explanation": "Limiting friction f = μN = μ(mg) = 0.2×5×10 = 10 N.", "topic": "Physics – Laws of Motion"}, {"q": "The average kinetic energy of one molecule of an ideal gas at temperature T is:", "options": ["(3/2)kT", "3RT", "kT", "(3/2)RT"], "answer": 0, "explanation": "Equipartition: (3/2)kT per molecule ((3/2)RT per mole).", "topic": "Physics – Kinetic Theory"}, {"q": "Light of photon energy 4 eV falls on a metal of work function 1 eV. The maximum kinetic energy of emitted electrons is:", "options": ["4 eV", "3 eV", "-3 eV", "5 eV"], "answer": 1, "explanation": "K_max = hν − φ = 4 − 1 = 3 eV.", "topic": "Physics – Modern Physics"}, {"q": "A buffer has [salt]/[acid] = 1 and pKa = 4.76. Its pH is:", "options": ["4.76 × 2", "5.76", "4.76", "3.76"], "answer": 2, "explanation": "pH = pKa + log([salt]/[acid]) = 4.76 + log(1) = 4.76.", "topic": "Chemistry – Equilibrium"}, {"q": "In a Wheatstone bridge, P = 4 Ω, Q = 2 Ω, R = 6 Ω. The unknown resistance S for balance is:", "options": ["3 Ω × 2", "3 Ω", "1.5 Ω", "12 Ω"], "answer": 1, "explanation": "Balance: P/Q = R/S ⇒ S = QR/P = 2×6/4 = 3 Ω.", "topic": "Physics – Current Electricity"}, {"q": "If y = 3x^4, then dy/dx equals:", "options": ["12x^4", "12x^3", "3x^3", "12x^5"], "answer": 1, "explanation": "dy/dx = 3×4x^3 = 12x^3.", "topic": "Maths – Differentiation"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 0.5 M, [B] = 2 M, [C] = 1 M. Kc equals:", "options": ["1", "1 × 2", "0.5", "2"], "answer": 0, "explanation": "Kc = [C]/([A][B]) = 1/(0.5×2) = 1.", "topic": "Chemistry – Equilibrium"}, {"q": "A radioactive sample has half-life 4 h. The fraction remaining after 8 h is:", "options": ["0.25", "0.5", "0.12", "1.25"], "answer": 0, "explanation": "Fraction = (1/2)^(t/T) = (1/2)^2 = 0.25.", "topic": "Physics – Modern Physics (numerical)"}, {"q": "A source of sound approaches a stationary observer. The observed frequency:", "options": ["increases", "becomes zero", "decreases", "remains unchanged"], "answer": 0, "explanation": "Approaching source compresses wavefronts: f' = f·v/(v − v_s) > f.", "topic": "Physics – Waves"}, {"q": "Haematite is an ore of:", "options": ["copper", "iron", "zinc", "aluminium"], "answer": 1, "explanation": "Haematite Fe2O3 is a major iron ore.", "topic": "Chemistry – s, p, d & f Block"}, {"q": "Which of the following is the dimensional formula of gravitational constant G is?", "options": ["[ML³T⁻²]", "[M⁻¹L³T⁻¹]", "[M⁻¹L²T⁻²]", "[M⁻¹L³T⁻²]"], "answer": 3, "explanation": "G = Fr²/m² gives [MLT⁻²][L²]/[M²] = [M⁻¹L³T⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "The bond angle in BF3 is:", "options": ["180°", "90°", "109.5°", "120°"], "answer": 3, "explanation": "Trigonal planar geometry gives 120° bond angles.", "topic": "Chemistry – Chemical Bonding"}, {"q": "A 2 kg mass moves in a circle of radius 5 m with speed 5 m/s. The centripetal force on it is:", "options": ["10 N", "5 N", "50 N", "2 N"], "answer": 0, "explanation": "Centripetal force F = mv²/r = 2×5²/5 = 10 N.", "topic": "Physics – Circular Motion"}, {"q": "The hybridization of sulphur in SF6 is:", "options": ["sp³", "sp³d²", "d²sp³ (inner)", "sp³d"], "answer": 1, "explanation": "SF6 has 6 bond pairs → octahedral, sp³d².", "topic": "Chemistry – Chemical Bonding"}, {"q": "A wire of length 1 m and cross-section 1 mm² is stretched by 2 mm under a force of 200 N. The elastic potential energy stored is:", "options": ["0.2 J", "0.4 J", "0.2 J × 2", "0.1 J"], "answer": 0, "explanation": "U = ½ × force × extension = ½×200×0 = 0.2 J.", "topic": "Physics – Elasticity"}, {"q": "The oxidation number of O in H2O2 is:", "options": ["+1", "−2", "−1", "0"], "answer": 2, "explanation": "2(+1) + 2x = 0 ⇒ x = −1 (peroxide linkage).", "topic": "Chemistry – Redox Reactions"}, {"q": "The value of ∫₀^2 x^1 dx is:", "options": ["4", "2", "2 × 2", "1"], "answer": 1, "explanation": "[x^2/2]₀^2 = 2^2/2 = 2.", "topic": "Maths – Definite Integrals"}, {"q": "If z = 4i, then z² + 4² equals:", "options": ["32", "-32", "4", "0"], "answer": 3, "explanation": "z² = (4i)² = −4², so z² + 4² = 0.", "topic": "Maths – Complex Numbers"}, {"q": "A particle starts from rest and moves with constant acceleration 5 m/s². Its speed after travelling 10 m is:", "options": ["10 m/s × 2", "5 m/s", "10 m/s", "20 m/s"], "answer": 2, "explanation": "Use v² = u² + 2as with u = 0: v = √(2×5×10) = 10 m/s.", "topic": "Physics – Kinematics"}, {"q": "The functional group –CONH2 is called:", "options": ["nitrile", "amide", "imide", "amine"], "answer": 1, "explanation": "–CONH2 is the amide functional group.", "topic": "Chemistry – Organic Chemistry"}, {"q": "A first-order reaction has rate constant k = 0.0347 min⁻¹. Its half-life is:", "options": ["9.99 min", "39.94 min", "19.97 min", "28.82 min"], "answer": 2, "explanation": "First order: t½ = 0.693/k = 0.693/0.0347 = 19.97 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "A Carnot engine operates between 400 K and 200 K. Its efficiency is:", "options": ["25%", "-100%", "50% × 2", "50%"], "answer": 3, "explanation": "η = 1 − T₂/T₁ = 1 − 200/400 = 50%.", "topic": "Physics – Thermodynamics"}, {"q": "The derivative of sin(3x) with respect to x is:", "options": ["−3cos(3x)", "3sin(3x)", "3cos(3x)", "cos(3x)"], "answer": 2, "explanation": "Chain rule: d/dx[sin(3x)] = 3cos(3x).", "topic": "Maths – Differentiation"}, {"q": "Which oxide is most basic?", "options": ["Na₂O", "SiO₂", "Al₂O₃", "MgO"], "answer": 0, "explanation": "Basic character of oxides decreases across a period; Na₂O is the most basic.", "topic": "Chemistry – Periodic Table"}, {"q": "In a single throw of a die, the probability of getting a number greater than 4 is:", "options": ["1/6", "0.33", "0.83", "1/2"], "answer": 1, "explanation": "Favourable outcomes: 5, …, 6 → 2 of 6 ⇒ 0.33.", "topic": "Maths – Probability"}, {"q": "The centre and radius of x² + y² − 6x − 4y + -3 = 0 are:", "options": ["(6, 4), 4", "(3, 2), 8", "(3, 2), 4", "(-3, -2), 4"], "answer": 2, "explanation": "Centre = (−g, −f) = (3, 2); radius = √(g² + f² − c) = 4.", "topic": "Maths – Circles"}, {"q": "The probability of getting a head when a fair coin is tossed twice (at least one head) is:", "options": ["1/2", "1", "3/4", "1/4"], "answer": 2, "explanation": "Outcomes: HH, HT, TH, TT — 3 of 4 have at least one head.", "topic": "Maths – Probability"}, {"q": "If det[[3, 1], [2, 3]] = x, then x equals:", "options": ["7", "14", "3.5", "8"], "answer": 0, "explanation": "x = 3×3 − 1×2 = 7.", "topic": "Maths – Matrices & Determinants (numerical)"}, {"q": "The moment of inertia of a thin ring of mass 2 kg and radius 2 m about its central axis is (MR²):", "options": ["4 kg·m²", "16 kg·m²", "8 kg·m² × 2", "8 kg·m²"], "answer": 3, "explanation": "I = MR² = 22² = 8 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "In a single throw of a die, the probability of getting a number greater than 5 is:", "options": ["1/6", "0.17", "1", "1/2"], "answer": 1, "explanation": "Favourable outcomes: 6, …, 6 → 1 of 6 ⇒ 0.17.", "topic": "Maths – Probability"}, {"q": "The wavelength of the photon emitted in the hydrogen transition n = 2 → 1 lies in the:", "options": ["microwave region", "visible region", "infrared region", "ultraviolet region"], "answer": 3, "explanation": "λ = 1240/ΔE nm ≈ 121.6 nm — the Lyman series.", "topic": "Chemistry – Atomic Structure"}, {"q": "∫ 2x^2 dx equals:", "options": ["2x^3 + C", "4x^1 + C", "0.67x^3 + C", "0.67x^2 + C"], "answer": 2, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 2x^3/3 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The oxidation number of N in NH4NO3 (ammonium N) is:", "options": ["−3", "+3", "+5", "0"], "answer": 0, "explanation": "In NH4⁺: x + 4(+1) = +1 ⇒ x = −3 (the nitrate N is +5).", "topic": "Chemistry – Redox Reactions"}, {"q": "For a cell with E° = -0.44 V, n = 1 and reaction quotient Q = 0.1, the cell emf at 298 K is:", "options": ["-0.19 V", "-0.44 V", "-0.5 V", "-0.38 V"], "answer": 3, "explanation": "Nernst: E = E° − (0.0591/n)logQ = -0.44 − (0.0591/1)log(0.1) = -0.38 V.", "topic": "Chemistry – Electrochemistry"}, {"q": "Electron affinity is highest for:", "options": ["F", "I", "Br", "Cl"], "answer": 3, "explanation": "Chlorine has the highest electron affinity (F's small size causes electron–electron repulsion).", "topic": "Chemistry – Periodic Table"}, {"q": "The freezing point depression of a 0.5 molal aqueous solution of urea (van't Hoff factor i = 1, Kf = 1.86 K·kg/mol) is:", "options": ["0.93 K × 2", "0.47 K", "0.93 K", "1.86 K"], "answer": 2, "explanation": "ΔTf = i·Kf·m = 1×1.86×0.5 = 0.93 K.", "topic": "Chemistry – Solutions"}, {"q": "The ratio of rates of effusion of H2 to O2 is:", "options": ["0.25", "16", "4", "2"], "answer": 2, "explanation": "Graham's law: r₁/r₂ = √(M₂/M₁) = √(32/2) = 4.", "topic": "Chemistry – Gaseous State"}, {"q": "In an LCR series circuit, L = 100 mH and C = 1 μF. The resonant frequency is:", "options": ["1006.58 Hz", "251.65 Hz", "503.29 Hz", "160.2 Hz"], "answer": 2, "explanation": "f₀ = 1/(2π√(LC)) = 1/(2π√(0.1×0)) = 503.29 Hz.", "topic": "Physics – EMI & AC"}, {"q": "The number of terms in the expansion of (x + y)^7 is:", "options": ["14", "8", "9", "7"], "answer": 1, "explanation": "(x + y)ⁿ expands to n + 1 = 8 terms.", "topic": "Maths – Binomial Theorem"}, {"q": "For A + B ⇌ C at equilibrium, [A] = 0.5 M, [B] = 2 M, [C] = 2 M. Kc equals:", "options": ["4", "1", "0.5", "2"], "answer": 3, "explanation": "Kc = [C]/([A][B]) = 2/(0.5×2) = 2.", "topic": "Chemistry – Equilibrium"}, {"q": "The centre and radius of x² + y² − 6x − 4y + 4 = 0 are:", "options": ["(3, 2), 6", "(6, 4), 3", "(3, 2), 3", "(-3, -2), 3"], "answer": 2, "explanation": "Centre = (−g, −f) = (3, 2); radius = √(g² + f² − c) = 3.", "topic": "Maths – Circles"}, {"q": "A mass of 0.25 kg attached to a spring of constant 25 N/m oscillates. Its time period is:", "options": ["0.63 s × 2", "0.63 s", "1.26 s", "0.31 s"], "answer": 1, "explanation": "T = 2π√(m/k) = 2π√(0.25/25) = 0.63 s.", "topic": "Physics – Oscillations"}, {"q": "Two vectors of magnitudes 4 and 5 units act at 90° to each other. The magnitude of their resultant is:", "options": ["1 units", "6.4 units × 2", "6.4 units", "9 units"], "answer": 2, "explanation": "R = √(A² + B² + 2ABcosθ) = √(4²+5²+2×4×5×cos90°) = 6.4 units.", "topic": "Physics – Vectors"}, {"q": "The limit of (x^2 − 2^2)/(x − 2) as x → 2 is:", "options": ["4 × 2", "8", "4", "2"], "answer": 2, "explanation": "Standard form: lim = n·aⁿ⁻¹ = 2×2ⁿ⁻¹ = 4.", "topic": "Maths – Limits"}, {"q": "The number of moles in 588 g of K2Cr2O7 (molar mass 294 g/mol) is:", "options": ["4 mol", "2 mol", "172872 mol", "1 mol"], "answer": 1, "explanation": "n = mass/molar mass = 588/294 = 2 mol.", "topic": "Chemistry – Mole Concept"}, {"q": "The order of the differential equation (d²y/dx²)³ + dy/dx = 0 is:", "options": ["6", "2", "3", "1"], "answer": 1, "explanation": "Order = highest derivative present = d²y/dx² → order 2 (power 3 is the degree).", "topic": "Maths – Differential Equations"}, {"q": "The volume occupied by 2 mol of an ideal gas at 2 atm and 273 K is (R = 0.0821 L·atm/mol·K):", "options": ["89.65 L", "22.41 L", "44.83 L", "11.21 L"], "answer": 1, "explanation": "V = nRT/P = 2×0.0821×273/2 = 22.41 L.", "topic": "Chemistry – Gaseous State"}, {"q": "Two point charges 1 μC and 3 μC are 0.5 m apart in vacuum. The electrostatic force between them is:", "options": ["0.11 N", "0.05 N", "1.08 N", "0.01 N"], "answer": 0, "explanation": "F = kq₁q₂/r² = 9×10⁹×1×3×10⁻¹²/0.5² = 0.11 N.", "topic": "Physics – Electrostatics"}, {"q": "The moment of inertia of a solid disc of mass 2 kg and radius 2 m about its central axis is (MR²/2):", "options": ["8 kg·m²", "2 kg·m²", "4 kg·m² × 2", "4 kg·m²"], "answer": 3, "explanation": "I = MR²/2 = 22²/2 = 4 kg·m².", "topic": "Physics – Rotational Motion"}, {"q": "The pH of a 0 M NaOH solution is:", "options": ["18", "10", "4", "5"], "answer": 1, "explanation": "[OH⁻] = 0 M ⇒ pOH = 4 ⇒ pH = 14 − 4 = 10.", "topic": "Chemistry – Equilibrium"}, {"q": "The electric field at a distance 0.2 m from a point charge of 4 μC is:", "options": ["900000 N/C", "180000 N/C", "1800000 N/C", "450000 N/C"], "answer": 0, "explanation": "E = kq/r² = 9×10⁹×4×10⁻⁶/0.2² = 900000 N/C.", "topic": "Physics – Electrostatics"}, {"q": "A first-order reaction has rate constant k = 0.1386 min⁻¹. Its half-life is:", "options": ["10 min", "2.5 min", "5 min", "7.22 min"], "answer": 2, "explanation": "First order: t½ = 0.693/k = 0.693/0.1386 = 5 min.", "topic": "Chemistry – Chemical Kinetics"}, {"q": "An electron (charge 1.6×10⁻¹⁹ C) enters a magnetic field of 1 T perpendicularly with speed 2×10⁶ m/s. The magnetic force on it is:", "options": ["0 N × 4", "0 N × 2", "0 N", "0 N × 3"], "answer": 2, "explanation": "F = qvB sin90° = 1.6×10⁻¹⁹×2×10⁶×1 = 0 N.", "topic": "Physics – Magnetism"}, {"q": "An electron with n = 4, l = 1, m = −1 is in which orbital?", "options": ["3p", "4s", "4d", "4p"], "answer": 3, "explanation": "l = 1 denotes a p orbital with n = 4.", "topic": "Chemistry – Atomic Structure"}, {"q": "The value of ∫₀^2 x^2 dx is:", "options": ["1.33", "2.67", "5.33", "4"], "answer": 1, "explanation": "[x^3/3]₀^2 = 2^3/3 = 2.67.", "topic": "Maths – Definite Integrals"}, {"q": "The determinant of [[5, 5], [4, 1]] is:", "options": ["5", "15", "25", "-15"], "answer": 3, "explanation": "det = ad − bc = 5×1 − 5×4 = -15.", "topic": "Maths – Matrices & Determinants"}, {"q": "Which of the following is the dimensional formula of force is?", "options": ["[MLT⁻¹]", "[MLT⁻²]", "[ML⁻¹T⁻²]", "[ML²T⁻²]"], "answer": 1, "explanation": "F = ma gives [M][LT⁻²] = [MLT⁻²].", "topic": "Physics – Units & Dimensions"}, {"q": "∫ 3x^3 dx equals:", "options": ["0.75x^3 + C", "9x^2 + C", "3x^4 + C", "0.75x^4 + C"], "answer": 3, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 3x^4/4 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "The bond order of N2 is:", "options": ["3.5", "3", "4", "2.5"], "answer": 1, "explanation": "Bond order = (bonding − antibonding electrons)/2; for N2 this equals 3.", "topic": "Chemistry – Chemical Bonding"}, {"q": "The energy of an electron in the n = 4 orbit of a hydrogen atom is:", "options": ["-1.7 eV", "-0.85 eV", "-0.42 eV", "0.85 eV"], "answer": 1, "explanation": "Eₙ = −13.6/n² = −13.6/4² = -0.85 eV.", "topic": "Physics – Modern Physics"}, {"q": "In a Wheatstone bridge, P = 2 Ω, Q = 2 Ω, R = 3 Ω. The unknown resistance S for balance is:", "options": ["3 Ω × 2", "3 Ω", "1.5 Ω", "7 Ω"], "answer": 1, "explanation": "Balance: P/Q = R/S ⇒ S = QR/P = 2×3/2 = 3 Ω.", "topic": "Physics – Current Electricity"}, {"q": "The escape velocity from Earth's surface (R = 6400 km, g = 10 m/s²) is approximately:", "options": ["8 km/s", "16 km/s", "7.9 km/s", "11.3 km/s"], "answer": 3, "explanation": "v_e = √(2gR) = √(2×10×6.4×10⁶) ≈ 11.3 km/s.", "topic": "Physics – Gravitation"}, {"q": "A 200 V, 2000 W-rated bulb has resistance 20 Ω. The power it consumes at 200 V is:", "options": ["4000 W", "2000 W", "2000 W × 2", "1000 W"], "answer": 1, "explanation": "P = V²/R = 200²/20 = 2000 W.", "topic": "Physics – Current Electricity"}, {"q": "Water flows through a pipe of cross-section 4 cm² at 2 m/s into a section of 1 cm². The speed there is:", "options": ["2 m/s", "8 m/s", "0.5 m/s", "16 m/s"], "answer": 1, "explanation": "Continuity: A₁v₁ = A₂v₂ ⇒ v₂ = 4×2/1 = 8.0 m/s.", "topic": "Physics – Fluid Mechanics"}, {"q": "∫ 2x^4 dx equals:", "options": ["0.4x^4 + C", "2x^5 + C", "8x^3 + C", "0.4x^5 + C"], "answer": 3, "explanation": "∫ xⁿ dx = xⁿ⁺¹/(n+1): 2x^5/5 + C.", "topic": "Maths – Indefinite Integrals"}, {"q": "Ozonolysis of 2-butene followed by Zn/H2O gives:", "options": ["2 molecules of formaldehyde", "1 molecule of butanedione", "acetic acid", "2 molecules of acetaldehyde"], "answer": 3, "explanation": "Each =CHCH3 fragment becomes CH3CHO; two fragments → 2 acetaldehyde.", "topic": "Chemistry – Organic Chemistry"}, {"q": "If sin x = 1/3, then cos²x equals:", "options": ["0.89", "0.67", "0.11", "1.11"], "answer": 0, "explanation": "cos²x = 1 − sin²x = 1 − 1/3² = 0.89.", "topic": "Maths – Trigonometry"}, {"q": "The oxidation number of Cr in K2Cr2O7 is:", "options": ["+6", "+7", "+3", "+4"], "answer": 0, "explanation": "2(+1) + 2x + 7(−2) = 0 ⇒ x = +6.", "topic": "Chemistry – Redox Reactions"}, {"q": "The sum of all binomial coefficients in (1 + x)^4 is:", "options": ["16 × 2", "8", "16", "10"], "answer": 2, "explanation": "Put x = 1: sum = (1+1)ⁿ = 2ⁿ = 16.", "topic": "Maths – Binomial Theorem"}, {"q": "The slope of the line y = 2x + 4 is:", "options": ["4", "2", "-2", "0.5"], "answer": 1, "explanation": "In y = mx + c, the slope is m = 2.", "topic": "Maths – Straight Lines"}, {"q": "A body of mass 10 kg has linear momentum 20 kg·m/s. Its kinetic energy is:", "options": ["20 J", "20 J × 2", "10 J", "40 J"], "answer": 0, "explanation": "KE = p²/(2m) = 20²/(2×10) = 20 J.", "topic": "Physics – Work, Energy & Power"}];
